-- Formulas
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_0454385f2e08f7', 'subj_math', 'standard-deviation', 'Sample standard deviation', 's = \sqrt{\frac{\sum (x_i - \bar{x})^2}{n - 1}}', 'The typical distance of data values from their mean, computed from a sample of n values.', '[{"symbol":"x_i","meaning":"data values"},{"symbol":"\\bar{x}","meaning":"sample mean"},{"symbol":"n","meaning":"sample size"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_8d7022925e5ae6', 'subj_math', 'least-squares-line', 'Least-squares regression line', '\hat{y} = a + bx, \qquad b = r\frac{s_y}{s_x}, \qquad a = \bar{y} - b\bar{x}', 'The line that minimizes the sum of squared residuals. It always passes through the point of means.', '[{"symbol":"r","meaning":"correlation"},{"symbol":"s_x, s_y","meaning":"standard deviations of x and y"},{"symbol":"\\bar{x}, \\bar{y}","meaning":"means of x and y"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_261c625a8be369', 'subj_math', 'expected-value', 'Mean and standard deviation of a discrete random variable', '\mu_X = \sum x_i p_i, \qquad \sigma_X = \sqrt{\sum (x_i - \mu_X)^2 p_i}', 'The long-run average value of a random variable and its typical variation from that average.', '[{"symbol":"x_i","meaning":"possible values"},{"symbol":"p_i","meaning":"their probabilities"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_cf8c13e3c87f8d', 'subj_math', 'binomial-probability', 'Binomial probability', 'P(X = k) = \binom{n}{k}p^k(1 - p)^{n - k}, \qquad \mu = np, \qquad \sigma = \sqrt{np(1 - p)}', 'Probability of exactly k successes in n independent trials, each with success probability p.', '[{"symbol":"n","meaning":"number of trials"},{"symbol":"k","meaning":"number of successes"},{"symbol":"p","meaning":"success probability per trial"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_fd1d0cd73a2a78', 'subj_math', 'proportion-interval', 'Confidence interval for a proportion', '\hat{p} \pm z^*\sqrt{\frac{\hat{p}(1 - \hat{p})}{n}}', 'An interval of plausible values for a population proportion p, built from a random sample. z* = 1.645, 1.96 and 2.576 for 90%, 95% and 99% confidence.', '[{"symbol":"\\hat{p}","meaning":"sample proportion"},{"symbol":"z^*","meaning":"critical value"},{"symbol":"n","meaning":"sample size"}]', 'published');

-- Lesson: binomial-distributions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_46888a18b5903a', 'binomial-distributions', 'Binomial distributions', 'Recognize binomial settings, compute binomial probabilities with the formula and complements, and find the mean and standard deviation of a binomial random variable.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3b4295f2fdf120', 'les_46888a18b5903a', 1, 'Check the binomial conditions: binary outcomes, independent trials, fixed number of trials, same probability of success.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2c62a7b91d85b6', 'les_46888a18b5903a', 2, 'Compute P(X = k) and ''at least'' probabilities.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a40f160886430a', 'les_46888a18b5903a', 3, 'Compute and interpret μ = np and σ = √(np(1 − p)).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3b4295f2fdf120', 'les_46888a18b5903a', 'learn', 1, 'definition', '{"term":"Binomial setting","body":"$n$ independent trials, each a success or failure, with the same success probability $p$. $X$ = the number of successes. (Sampling without replacement is close enough to independent if the sample is less than 10% of the population.)"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2c62a7b91d85b6', 'les_46888a18b5903a', 'learn', 2, 'definition', '{"term":"Binomial probability","body":"$P(X = k) = \\binom{n}{k}p^k(1 - p)^{n - k}$. The $\\binom{n}{k}$ counts the arrangements of $k$ successes among $n$ trials."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a40f160886430a', 'les_46888a18b5903a', 'learn', 3, 'worked_example', '{"title":"A basketball player makes 30% of her 3-point shots. In 5 independent shots, find $P(X = 2)$.","steps":[{"latex":"\\binom{5}{2}(0.3)^2(0.7)^3 = 10 \\cdot 0.09 \\cdot 0.343","explanation":""},{"latex":"= 0.3087","explanation":""},{"latex":"\\mu = 5(0.3) = 1.5,\\ \\sigma = \\sqrt{5(0.3)(0.7)} \\approx 1.02","explanation":"On average 1.5 makes per 5 shots."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b5df9f9be73279', 'les_46888a18b5903a', 'learn', 4, 'callout', '{"tone":"tip","title":"At least one","body":"$P(X \\ge 1) = 1 - P(X = 0) = 1 - (1 - p)^n$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2352829a03d541', 'les_46888a18b5903a', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Quality control (defective items in a batch), clinical trials (patients who respond), and genetics (offspring with a trait) all use binomial models."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3b4295f2fdf120', 'les_46888a18b5903a', 1, 'practice', 'numeric', 1, 'Flip a fair coin 4 times. Find $P(\text{exactly 3 heads})$.', '{"answer":0.25,"tolerance":0.001}', '[]', '$\binom{4}{3}(0.5)^4 = \frac{4}{16} = 0.25$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2c62a7b91d85b6', 'les_46888a18b5903a', 2, 'practice', 'numeric', 1, '$n = 20$, $p = 0.1$. Find the mean number of successes.', '{"answer":2}', '[]', '$np = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a40f160886430a', 'les_46888a18b5903a', 3, 'practice', 'numeric', 2, 'Each of 3 independent parts is defective with probability 0.2. Find $P(\text{at least one defective})$.', '{"answer":0.488,"tolerance":0.001}', '[]', '$1 - 0.8^3 = 1 - 0.512 = 0.488$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b5df9f9be73279', 'les_46888a18b5903a', 4, 'practice', 'multiple_choice', 2, 'Which is NOT a binomial setting?', '{"choices":["Counting heads in 10 coin flips","Counting rolls until the first 6","Counting correct guesses on 20 true/false questions","Counting defective bulbs in a random sample of 15 from a large shipment"],"answer":1}', '[]', 'The number of trials isn''t fixed: that''s a geometric setting.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2352829a03d541', 'les_46888a18b5903a', 5, 'review', 'numeric', 3, '$n = 100$, $p = 0.5$. Find $\sigma$.', '{"answer":5,"tolerance":0.001}', '[]', '$\sqrt{100(0.5)(0.5)} = 5$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_edd54efaadfef2', 'subj_math', 'random-variables', 'Random variables', 'Numerical outcomes of random processes, described by probability distributions with a mean and standard deviation.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_46888a18b5903a', (SELECT id FROM concepts WHERE slug = 'random-variables'));
