-- Lesson: combining-random-variables
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9d1eea66e1b82d', 'combining-random-variables', 'Combining random variables', 'Find the mean and standard deviation of linear transformations aX + b, and of sums and differences of independent random variables, where variances add.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3ab25964f63e29', 'les_9d1eea66e1b82d', 1, 'Find the mean and standard deviation of a + bX.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4c41c1d7799ffe', 'les_9d1eea66e1b82d', 2, 'Find the mean of X ± Y for any random variables.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_737416585383d9', 'les_9d1eea66e1b82d', 3, 'Find the standard deviation of X ± Y for independent random variables by adding variances.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3ab25964f63e29', 'les_9d1eea66e1b82d', 'learn', 1, 'definition', '{"term":"Linear transformations","body":"For $Y = a + bX$: $\\mu_Y = a + b\\mu_X$ and $\\sigma_Y = |b|\\sigma_X$. Adding a constant shifts the center but not the spread."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4c41c1d7799ffe', 'les_9d1eea66e1b82d', 'learn', 2, 'definition', '{"term":"Sums and differences","body":"$\\mu_{X \\pm Y} = \\mu_X \\pm \\mu_Y$ always. If $X$ and $Y$ are independent, $\\sigma^2_{X \\pm Y} = \\sigma_X^2 + \\sigma_Y^2$: variances add, even for a difference."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_737416585383d9', 'les_9d1eea66e1b82d', 'learn', 3, 'worked_example', '{"title":"Shower time $X$: mean 8 min, SD 2 min. Dressing time $Y$: mean 5 min, SD 1.5 min, independent.","steps":[{"latex":"\\mu_{X + Y} = 13 \\text{ min}","explanation":""},{"latex":"\\sigma_{X + Y} = \\sqrt{2^2 + 1.5^2} = \\sqrt{6.25} = 2.5 \\text{ min}","explanation":"Add variances, not standard deviations."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9252273245bc99', 'les_9d1eea66e1b82d', 'learn', 4, 'worked_example', '{"title":"Temperatures in °C have mean 20 and SD 5. Convert to °F with $F = 1.8C + 32$.","steps":[{"latex":"\\mu_F = 1.8(20) + 32 = 68","explanation":""},{"latex":"\\sigma_F = 1.8(5) = 9","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a3109f59c10858', 'les_9d1eea66e1b82d', 'learn', 5, 'callout', '{"tone":"warning","title":"Why differences add variance","body":"Subtracting one random quantity from another doesn''t cancel uncertainty; both sources of variation remain. The variance of $X - Y$ is the same as that of $X + Y$ when they''re independent."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c654c4dc851474', 'les_9d1eea66e1b82d', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Engineers stack part tolerances this way: the total length of several parts has a standard deviation equal to the square root of the summed variances."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3ab25964f63e29', 'les_9d1eea66e1b82d', 1, 'practice', 'numeric', 2, '$X$ and $Y$ are independent with $\sigma_X = 3$ and $\sigma_Y = 4$. Find $\sigma_{X - Y}$.', '{"answer":5}', '[]', '$\sqrt{9 + 16} = 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4c41c1d7799ffe', 'les_9d1eea66e1b82d', 2, 'practice', 'numeric', 1, '$\mu_X = 10$, $\mu_Y = 4$. Find $\mu_{X - Y}$.', '{"answer":6}', '[]', '$10 - 4 = 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_737416585383d9', 'les_9d1eea66e1b82d', 3, 'practice', 'numeric', 2, '$\sigma_X = 6$. Find the standard deviation of $Y = 50 - 2X$.', '{"answer":12}', '[]', '$|-2| \cdot 6 = 12$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9252273245bc99', 'les_9d1eea66e1b82d', 4, 'review', 'multiple_choice', 3, 'Three independent boxes each weigh mean 10 kg, SD 1 kg. The SD of the total weight is…', '{"choices":["3 kg","$\\sqrt{3} \\approx 1.73$ kg","1 kg","9 kg"],"answer":1}', '[]', 'Variances add: $1 + 1 + 1 = 3$, so $\sigma = \sqrt{3}$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_edd54efaadfef2', 'subj_math', 'random-variables', 'Random variables', 'Numerical outcomes of random processes, described by probability distributions with a mean and standard deviation.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9d1eea66e1b82d', (SELECT id FROM concepts WHERE slug = 'random-variables'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_9d1eea66e1b82d', (SELECT id FROM formulas WHERE slug = 'expected-value'), 1);

-- Lesson: comparing-distributions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_74efdb6f6ac0ee', 'comparing-distributions', 'Comparing distributions', 'Compare two or more distributions using parallel displays and comparative language for shape, center, spread and outliers.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_985d71e343e12e', 'les_74efdb6f6ac0ee', 1, 'Use parallel box plots, back-to-back stemplots or stacked dot plots to compare groups.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_386bc7cb55c449', 'les_74efdb6f6ac0ee', 2, 'Compare centers and spreads with explicit comparative language.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_baa701517fd3b2', 'les_74efdb6f6ac0ee', 3, 'Avoid conclusions that the data can''t support.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_985d71e343e12e', 'les_74efdb6f6ac0ee', 'learn', 1, 'definition', '{"term":"Comparing, not just describing","body":"A comparison uses words like \"greater than\", \"about the same as\" and \"more variable than\". Describing each group separately isn''t a comparison."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_386bc7cb55c449', 'les_74efdb6f6ac0ee', 'learn', 2, 'worked_example', '{"title":"Quiz scores. Class A: median 78, IQR 12, symmetric. Class B: median 72, IQR 20, skewed left, low outlier at 31.","steps":[{"latex":"\\text{center: A''s median is 6 points higher than B''s}","explanation":""},{"latex":"\\text{spread: B''s scores are more variable (IQR 20 vs 12)}","explanation":""},{"latex":"\\text{shape and outliers: A symmetric; B skewed left with a low outlier}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_baa701517fd3b2', 'les_74efdb6f6ac0ee', 'learn', 3, 'callout', '{"tone":"warning","title":"Don''t overreach","body":"If these are two class sections, the difference doesn''t prove one teacher is better: the students weren''t randomly assigned. Comparisons of existing groups describe differences; they don''t explain them."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_98e7574a0312d7', 'les_74efdb6f6ac0ee', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Doctors compare blood-pressure distributions for treatment and control groups; manufacturers compare output from two machines for consistency (spread), not just average (center)."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_985d71e343e12e', 'les_74efdb6f6ac0ee', 1, 'practice', 'numeric', 1, 'Group 1 has median 45 and Group 2 has median 38. How much greater is Group 1''s median?', '{"answer":7}', '[]', '$45 - 38 = 7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_386bc7cb55c449', 'les_74efdb6f6ac0ee', 2, 'practice', 'multiple_choice', 2, 'Machine X fills bottles with SD 1.2 mL; Machine Y with SD 3.5 mL. Both average 500 mL. Which is more consistent?', '{"choices":["X","Y","They''re the same","Can''t tell"],"answer":0}', '[]', 'Smaller standard deviation means less variation.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_baa701517fd3b2', 'les_74efdb6f6ac0ee', 3, 'practice', 'multiple_choice', 2, 'Which statement is a comparison?', '{"choices":["Boys'' heights have a median of 68 in.","Girls'' heights are symmetric.","Boys'' median height is about 4 in. greater than girls'', and the two have similar spreads.","Heights vary."],"answer":2}', '[]', 'It relates the two groups directly.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_98e7574a0312d7', 'les_74efdb6f6ac0ee', 4, 'review', 'multiple_choice', 3, 'Parallel box plots show that students who sleep more have higher median GPAs. What can you conclude?', '{"choices":["More sleep causes higher GPA","There is an association between sleep and GPA in these data","Higher GPA causes more sleep","Nothing"],"answer":1}', '[]', 'This is observational data: an association, not cause and effect.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_0f43887800fc3d', 'subj_math', 'distributions', 'Distributions', 'The values a variable takes and how often it takes them.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_74efdb6f6ac0ee', (SELECT id FROM concepts WHERE slug = 'distributions'));

-- Lesson: comparing-two-means
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_972a7199a48001', 'comparing-two-means', 'Comparing two means', 'Estimate and test the difference between two population means with two-sample t procedures, and distinguish them from paired data.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0d011c68f2e630', 'les_972a7199a48001', 1, 'Compute the standard error √(s₁²/n₁ + s₂²/n₂) and a two-sample t statistic.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_000e2d099dcb62', 'les_972a7199a48001', 2, 'Build and interpret a t interval for μ₁ − μ₂.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2b9ce86f1d2d9f', 'les_972a7199a48001', 3, 'Recognize paired data, which call for a one-sample analysis of differences.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0d011c68f2e630', 'les_972a7199a48001', 'learn', 1, 'definition', '{"term":"Two-sample t procedures","body":"Interval: $(\\bar{x}_1 - \\bar{x}_2) \\pm t^*\\sqrt{\\frac{s_1^2}{n_1} + \\frac{s_2^2}{n_2}}$. Test of $H_0: \\mu_1 = \\mu_2$: $t = \\frac{\\bar{x}_1 - \\bar{x}_2}{\\sqrt{s_1^2/n_1 + s_2^2/n_2}}$. Technology gives the degrees of freedom; a conservative choice is the smaller of $n_1 - 1$ and $n_2 - 1$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_000e2d099dcb62', 'les_972a7199a48001', 'learn', 2, 'worked_example', '{"title":"Test scores. Method A: $n_1 = 30$, $\\bar{x}_1 = 78$, $s_1 = 10$. Method B: $n_2 = 35$, $\\bar{x}_2 = 72$, $s_2 = 12$. Test $H_a: \\mu_1 \\ne \\mu_2$.","steps":[{"latex":"SE = \\sqrt{\\tfrac{100}{30} + \\tfrac{144}{35}} = \\sqrt{3.333 + 4.114} \\approx 2.73","explanation":""},{"latex":"t = \\frac{6}{2.73} \\approx 2.20","explanation":""},{"latex":"\\text{P-value} \\approx 0.04 \\ (df = 29 \\text{ conservative})","explanation":"Less than 0.05: convincing evidence the mean scores differ."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2b9ce86f1d2d9f', 'les_972a7199a48001', 'learn', 3, 'definition', '{"term":"Paired data","body":"If the two measurements come in natural pairs (same person before and after, twins, matched subjects), compute each pair''s difference and use one-sample t procedures on the differences. Treating paired data as two independent samples wastes the pairing."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cdebe2d4188d3f', 'les_972a7199a48001', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Agricultural trials compare mean yields of two varieties; studies of training programs compare before-and-after scores with paired t procedures."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0d011c68f2e630', 'les_972a7199a48001', 1, 'practice', 'numeric', 1, '$\bar{x}_1 = 54$ and $\bar{x}_2 = 49$. Find the observed difference $\bar{x}_1 - \bar{x}_2$.', '{"answer":5}', '[]', '$54 - 49 = 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_000e2d099dcb62', 'les_972a7199a48001', 2, 'practice', 'numeric', 2, '$s_1 = 4$, $n_1 = 16$, $s_2 = 3$, $n_2 = 9$. Find the standard error to three decimal places.', '{"answer":1.414,"tolerance":0.001}', '[]', '$\sqrt{\frac{16}{16} + \frac{9}{9}} = \sqrt{2} \approx 1.414$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2b9ce86f1d2d9f', 'les_972a7199a48001', 3, 'practice', 'multiple_choice', 2, 'Each of 20 students takes a test before and after tutoring. Which procedure fits?', '{"choices":["Two-sample t","Paired t on the differences","Two-proportion z","Binomial"],"answer":1}', '[]', 'The measurements are paired by student.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cdebe2d4188d3f', 'les_972a7199a48001', 4, 'review', 'multiple_choice', 3, 'A 95% interval for $\mu_1 - \mu_2$ is (2.1, 9.8). Which is true?', '{"choices":["The means are equal","μ₁ is plausibly larger by about 2 to 10 units","μ₂ is larger","The test would fail to reject"],"answer":1}', '[]', 'The interval lies entirely above 0.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_a06d7d05166ca6', 'subj_math', 'confidence-intervals', 'Confidence intervals', 'Intervals of plausible values for a population parameter, built from sample data with a stated confidence level.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_972a7199a48001', (SELECT id FROM concepts WHERE slug = 'confidence-intervals'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d1e1e71a856b16', 'subj_math', 'significance-tests', 'Significance tests', 'Procedures that use sample data to weigh evidence against a claim about a population parameter.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_972a7199a48001', (SELECT id FROM concepts WHERE slug = 'significance-tests'));

-- Lesson: comparing-two-proportions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_b7fd6c2d4ca31e', 'comparing-two-proportions', 'Comparing two proportions', 'Estimate and test the difference between two population proportions using independent random samples or a randomized experiment.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d022688f6c9ef9', 'les_b7fd6c2d4ca31e', 1, 'Compute a confidence interval for p₁ − p₂.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_73069432a2a524', 'les_b7fd6c2d4ca31e', 2, 'Carry out a two-sample z test using the pooled proportion.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_357213acd5005c', 'les_b7fd6c2d4ca31e', 3, 'Interpret results in context, including whether 0 is a plausible difference.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d022688f6c9ef9', 'les_b7fd6c2d4ca31e', 'learn', 1, 'definition', '{"term":"Interval for p₁ − p₂","body":"$(\\hat{p}_1 - \\hat{p}_2) \\pm z^*\\sqrt{\\frac{\\hat{p}_1(1 - \\hat{p}_1)}{n_1} + \\frac{\\hat{p}_2(1 - \\hat{p}_2)}{n_2}}$. Conditions: two independent random samples (or random assignment), 10% for each, and at least 10 successes and 10 failures in each group."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_73069432a2a524', 'les_b7fd6c2d4ca31e', 'learn', 2, 'definition', '{"term":"Test of H₀: p₁ = p₂","body":"Use the pooled proportion $\\hat{p}_c = \\frac{x_1 + x_2}{n_1 + n_2}$: $z = \\frac{\\hat{p}_1 - \\hat{p}_2}{\\sqrt{\\hat{p}_c(1 - \\hat{p}_c)\\left(\\frac{1}{n_1} + \\frac{1}{n_2}\\right)}}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_357213acd5005c', 'les_b7fd6c2d4ca31e', 'learn', 3, 'worked_example', '{"title":"In a randomized experiment, 120 of 200 patients improved on a new drug and 90 of 200 on the standard drug. Build a 95% interval.","steps":[{"latex":"\\hat{p}_1 = 0.60,\\ \\hat{p}_2 = 0.45,\\ \\text{difference } 0.15","explanation":""},{"latex":"SE = \\sqrt{\\tfrac{0.6 \\cdot 0.4}{200} + \\tfrac{0.45 \\cdot 0.55}{200}} \\approx 0.0494","explanation":""},{"latex":"0.15 \\pm 1.96(0.0494) = 0.15 \\pm 0.097","explanation":""},{"latex":"(0.053,\\ 0.247)","explanation":"0 isn''t in the interval: convincing evidence the new drug''s improvement rate is higher."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5a3a434ea3a51b', 'les_b7fd6c2d4ca31e', 'learn', 4, 'callout', '{"tone":"tip","title":"Why pool for the test?","body":"The test assumes $H_0: p_1 = p_2$, so we combine both samples to estimate that one common proportion."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a7d0d4c84605e2', 'les_b7fd6c2d4ca31e', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"A/B tests compare click-through rates for two web page designs; vaccine trials compare infection rates between vaccine and placebo groups."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d022688f6c9ef9', 'les_b7fd6c2d4ca31e', 1, 'practice', 'numeric', 1, 'Group 1: 60 of 200 succeed. Group 2: 50 of 200. Find $\hat{p}_1 - \hat{p}_2$.', '{"answer":0.05,"tolerance":0.001}', '[]', '$0.30 - 0.25 = 0.05$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_73069432a2a524', 'les_b7fd6c2d4ca31e', 2, 'practice', 'numeric', 2, 'For those groups, find the pooled proportion $\hat{p}_c$.', '{"answer":0.275,"tolerance":0.001}', '[]', '$\frac{110}{400} = 0.275$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_357213acd5005c', 'les_b7fd6c2d4ca31e', 3, 'practice', 'multiple_choice', 2, 'A 95% interval for $p_1 - p_2$ is $(-0.04, 0.10)$. What can you conclude?', '{"choices":["p₁ is definitely larger","p₂ is definitely larger","No convincing evidence of a difference; 0 is plausible","The samples are biased"],"answer":2}', '[]', 'The interval contains 0.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5a3a434ea3a51b', 'les_b7fd6c2d4ca31e', 4, 'review', 'multiple_choice', 3, 'Why can the drug example support a cause-and-effect conclusion?', '{"choices":["The samples were large","Patients were randomly assigned to treatments","The difference was positive","It used a 95% level"],"answer":1}', '[]', 'Random assignment makes the groups comparable apart from the treatment.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_a06d7d05166ca6', 'subj_math', 'confidence-intervals', 'Confidence intervals', 'Intervals of plausible values for a population parameter, built from sample data with a stated confidence level.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_b7fd6c2d4ca31e', (SELECT id FROM concepts WHERE slug = 'confidence-intervals'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d1e1e71a856b16', 'subj_math', 'significance-tests', 'Significance tests', 'Procedures that use sample data to weigh evidence against a claim about a population parameter.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_b7fd6c2d4ca31e', (SELECT id FROM concepts WHERE slug = 'significance-tests'));

-- Lesson: confidence-intervals-mean
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_1932486c137f7d', 'confidence-intervals-mean', 'Confidence intervals for a mean', 'Construct and interpret a t interval for a population mean, use t distributions with n − 1 degrees of freedom, and check the conditions.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_04103a5710df34', 'les_1932486c137f7d', 1, 'Explain why we use t* instead of z* when σ is unknown.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_44f9e995bd248a', 'les_1932486c137f7d', 2, 'Compute x̄ ± t*·s/√n with n − 1 degrees of freedom.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2340b4cbd3cc42', 'les_1932486c137f7d', 3, 'Check the Random, 10% and Normal/Large Sample conditions.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_04103a5710df34', 'les_1932486c137f7d', 'learn', 1, 'definition', '{"term":"t distributions","body":"When we estimate $\\sigma$ with the sample SD $s$, the standardized statistic follows a $t$ distribution with $n - 1$ degrees of freedom. It''s bell-shaped like the normal but with heavier tails, so $t^* > z^*$; as $n$ grows it approaches the normal."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_44f9e995bd248a', 'les_1932486c137f7d', 'learn', 2, 'definition', '{"term":"The interval","body":"$\\bar{x} \\pm t^*\\frac{s}{\\sqrt{n}}$. Conditions: Random; $n \\le 10\\%$ of the population; and the population is approximately normal, or $n \\ge 30$, or the sample shows no strong skew or outliers."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2340b4cbd3cc42', 'les_1932486c137f7d', 'learn', 3, 'worked_example', '{"title":"A random sample of 16 batteries lasts a mean of 52 hours with $s = 8$. Build a 95% interval.","steps":[{"latex":"df = 15,\\ t^* = 2.131","explanation":"From a t table or technology."},{"latex":"SE = \\frac{8}{\\sqrt{16}} = 2","explanation":""},{"latex":"52 \\pm 2.131(2) = 52 \\pm 4.26","explanation":""},{"latex":"(47.7,\\ 56.3) \\text{ hours}","explanation":"We are 95% confident the true mean battery life is in this interval."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8c9f78b3db580f', 'les_1932486c137f7d', 'learn', 4, 'callout', '{"tone":"tip","title":"Width depends on three things","body":"Larger confidence → wider. Larger $s$ → wider. Larger $n$ → narrower (by a factor of $\\sqrt{n}$)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_24ba61bdd05afd', 'les_1932486c137f7d', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Manufacturers estimate mean product lifetimes, and researchers report mean blood pressure changes, with t intervals."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_04103a5710df34', 'les_1932486c137f7d', 1, 'practice', 'numeric', 1, 'Find the standard error $\frac{s}{\sqrt{n}}$ for $s = 10$ and $n = 25$.', '{"answer":2}', '[]', '$\frac{10}{5} = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_44f9e995bd248a', 'les_1932486c137f7d', 2, 'practice', 'multiple_choice', 2, 'For the same confidence level, $t^*$ with 5 degrees of freedom is…', '{"choices":["smaller than $z^*$","larger than $z^*$","equal to $z^*$","negative"],"answer":1}', '[]', 'Heavier tails mean larger critical values.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2340b4cbd3cc42', 'les_1932486c137f7d', 3, 'practice', 'numeric', 2, 'A 95% t interval uses $t^* = 2.064$, $\bar{x} = 30$ and $SE = 1.5$. Find the upper bound to two decimal places.', '{"answer":33.1,"tolerance":0.01}', '[]', '$30 + 2.064(1.5) = 33.096 \approx 33.10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8c9f78b3db580f', 'les_1932486c137f7d', 4, 'review', 'multiple_choice', 3, 'A sample of 12 has a strongly skewed dot plot with an outlier. Is a t interval appropriate?', '{"choices":["Yes, always","No: the Normal/Large Sample condition isn''t met","Yes, because n < 30","Only at 99% confidence"],"answer":1}', '[]', 'With a small sample, strong skew and outliers make the t procedure unreliable.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_a06d7d05166ca6', 'subj_math', 'confidence-intervals', 'Confidence intervals', 'Intervals of plausible values for a population parameter, built from sample data with a stated confidence level.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_1932486c137f7d', (SELECT id FROM concepts WHERE slug = 'confidence-intervals'));

-- Lesson: confidence-intervals-proportion
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_366d29bb1a3551', 'confidence-intervals-proportion', 'Confidence intervals for a proportion', 'Construct and interpret a confidence interval for a population proportion, check its conditions, and explain what the confidence level means.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2de1395f320684', 'les_366d29bb1a3551', 1, 'Check the Random, 10% and Large Counts conditions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6afcc279ad1585', 'les_366d29bb1a3551', 2, 'Compute p̂ ± z*√(p̂(1 − p̂)/n).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_eb1e09cf67df74', 'les_366d29bb1a3551', 3, 'Interpret the interval and the confidence level correctly.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2de1395f320684', 'les_366d29bb1a3551', 'learn', 1, 'definition', '{"term":"The interval","body":"$\\hat{p} \\pm z^*\\sqrt{\\frac{\\hat{p}(1 - \\hat{p})}{n}}$, where $z^* = 1.645$, $1.96$ or $2.576$ for 90%, 95% or 99% confidence. The second term is the margin of error."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6afcc279ad1585', 'les_366d29bb1a3551', 'learn', 2, 'definition', '{"term":"Conditions","body":"Random: the data come from a random sample. 10%: $n$ is at most 10% of the population. Large Counts: $n\\hat{p} \\ge 10$ and $n(1 - \\hat{p}) \\ge 10$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eb1e09cf67df74', 'les_366d29bb1a3551', 'learn', 3, 'worked_example', '{"title":"In a random sample of 500 voters, 270 support a measure. Build a 95% interval.","steps":[{"latex":"\\hat{p} = 0.54;\\ 500(0.54) = 270 \\ge 10,\\ 500(0.46) = 230 \\ge 10","explanation":"Conditions met (assuming many more than 5,000 voters)."},{"latex":"SE = \\sqrt{\\tfrac{0.54 \\cdot 0.46}{500}} \\approx 0.0223","explanation":""},{"latex":"0.54 \\pm 1.96(0.0223) = 0.54 \\pm 0.044","explanation":""},{"latex":"(0.496,\\ 0.584)","explanation":""}],"check":"Interpretation: we are 95% confident that between 49.6% and 58.4% of all voters support the measure. Since the interval includes values below 50%, a majority isn''t certain."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9a1024fdee3691', 'les_366d29bb1a3551', 'learn', 4, 'callout', '{"tone":"warning","title":"What 95% confidence means","body":"If we took many random samples and built an interval from each, about 95% of those intervals would capture the true $p$. It does not mean there''s a 95% probability that $p$ is in this particular interval."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a87dd5c972734e', 'les_366d29bb1a3551', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Election polls, product defect rates and vaccination coverage surveys report confidence intervals, often as \"± 3 percentage points.\""}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2de1395f320684', 'les_366d29bb1a3551', 1, 'practice', 'numeric', 1, 'Find the 95% margin of error for $\hat{p} = 0.5$ and $n = 400$, to three decimal places.', '{"answer":0.049,"tolerance":0.001}', '[]', '$1.96\sqrt{\frac{0.25}{400}} = 1.96(0.025) = 0.049$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6afcc279ad1585', 'les_366d29bb1a3551', 2, 'practice', 'numeric', 2, 'Find the lower bound of a 90% interval for $\hat{p} = 0.3$, $n = 100$, to three decimal places.', '{"answer":0.225,"tolerance":0.002}', '["$SE = \\sqrt{0.21/100} \\approx 0.0458$."]', '$0.3 - 1.645(0.0458) \approx 0.3 - 0.075 = 0.225$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eb1e09cf67df74', 'les_366d29bb1a3551', 3, 'practice', 'multiple_choice', 2, 'Going from 95% to 99% confidence with the same data makes the interval…', '{"choices":["narrower","wider","the same width","centered elsewhere"],"answer":1}', '[]', 'A larger $z^*$ means a larger margin of error.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9a1024fdee3691', 'les_366d29bb1a3551', 4, 'practice', 'multiple_choice', 2, 'A sample of 40 finds 3 successes. Which condition fails?', '{"choices":["Random","10%","Large Counts","None"],"answer":2}', '[]', '$n\hat{p} = 3 < 10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a87dd5c972734e', 'les_366d29bb1a3551', 5, 'review', 'multiple_choice', 3, 'A 95% interval for the proportion of students who walk to school is (0.12, 0.20). Which interpretation is correct?', '{"choices":["95% of students walk","There''s a 95% chance p is between 0.12 and 0.20","We are 95% confident the true proportion of students who walk is between 0.12 and 0.20","95% of samples have p̂ between 0.12 and 0.20"],"answer":2}', '[]', 'Confidence is about the method''s long-run success rate.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_a06d7d05166ca6', 'subj_math', 'confidence-intervals', 'Confidence intervals', 'Intervals of plausible values for a population parameter, built from sample data with a stated confidence level.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_366d29bb1a3551', (SELECT id FROM concepts WHERE slug = 'confidence-intervals'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_366d29bb1a3551', (SELECT id FROM formulas WHERE slug = 'proportion-interval'), 1);

-- Lesson: correlation
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_1469596fc89ae5', 'correlation', 'Correlation', 'Measure the direction and strength of a linear relationship with the correlation coefficient r, compute it for small data sets, and know its properties and limits.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f31e88053f2822', 'les_1469596fc89ae5', 1, 'Interpret r in terms of direction and strength of a linear association.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7fb51c40e62676', 'les_1469596fc89ae5', 2, 'Compute r from standardized values for a small data set.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ba8e80216dc506', 'les_1469596fc89ae5', 3, 'State the properties of r: unitless, between −1 and 1, sensitive to outliers, linear only, and not evidence of causation.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f31e88053f2822', 'les_1469596fc89ae5', 'learn', 1, 'definition', '{"term":"Correlation coefficient","body":"$r = \\frac{1}{n - 1}\\sum z_x z_y$, the average product of the standardized values. Equivalently, $r = \\frac{\\sum (x - \\bar{x})(y - \\bar{y})}{\\sqrt{\\sum (x - \\bar{x})^2 \\sum (y - \\bar{y})^2}}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7fb51c40e62676', 'les_1469596fc89ae5', 'learn', 2, 'worked_example', '{"title":"$x$: 1, 2, 3, 4, 5 and $y$: 2, 4, 5, 4, 5","steps":[{"latex":"\\bar{x} = 3,\\ \\bar{y} = 4","explanation":""},{"latex":"\\sum (x - \\bar{x})(y - \\bar{y}) = 4 + 0 + 0 + 0 + 2 = 6","explanation":""},{"latex":"\\sum (x - \\bar{x})^2 = 10,\\ \\sum (y - \\bar{y})^2 = 6","explanation":""},{"latex":"r = \\frac{6}{\\sqrt{60}} \\approx 0.775","explanation":"A fairly strong positive linear association."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ba8e80216dc506', 'les_1469596fc89ae5', 'learn', 3, 'definition', '{"term":"Properties","body":"$-1 \\le r \\le 1$; the sign gives direction; $|r|$ near 1 means points lie close to a line. $r$ has no units and doesn''t change if you change units or swap $x$ and $y$. It measures only linear association and is strongly affected by outliers."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a457a4dd4b74f1', 'les_1469596fc89ae5', 'learn', 4, 'callout', '{"tone":"warning","title":"Correlation is not causation","body":"Ice-cream sales and drownings are positively correlated: both rise in hot weather, a lurking variable. Only a randomized experiment can show cause and effect."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5dee896c52cb0b', 'les_1469596fc89ae5', 'learn', 5, 'callout', '{"tone":"warning","title":"r = 0 doesn''t mean no relationship","body":"Points on a parabola like $y = x^2$ for $x$ from −3 to 3 have $r = 0$ even though $y$ is determined exactly by $x$. Always look at the scatterplot."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1a29e9474075ee', 'les_1469596fc89ae5', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Investors use correlation between assets to build diversified portfolios; scientists report correlations as a first step before running experiments."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f31e88053f2822', 'les_1469596fc89ae5', 1, 'practice', 'multiple_choice', 1, 'Which $r$ shows the strongest linear relationship?', '{"choices":["0.62","−0.91","0.05","0.88"],"answer":1}', '[]', 'Strength is $|r|$; the sign is direction.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7fb51c40e62676', 'les_1469596fc89ae5', 2, 'practice', 'multiple_choice', 2, 'Heights are converted from inches to centimeters. What happens to $r$ between height and weight?', '{"choices":["It is multiplied by 2.54","It doesn''t change","It becomes 1","It changes sign"],"answer":1}', '[]', '$r$ is unitless.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ba8e80216dc506', 'les_1469596fc89ae5', 3, 'practice', 'numeric', 2, 'For $x$: 1, 2, 3 and $y$: 3, 1, 2, compute $r$.', '{"answer":-0.5,"tolerance":0.001}', '["$\\bar{x} = 2$, $\\bar{y} = 2$."]', 'Products: $(-1)(1) + 0 + (1)(0) = -1$. $\sum dx^2 = 2$, $\sum dy^2 = 2$. $r = \frac{-1}{2} = -0.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a457a4dd4b74f1', 'les_1469596fc89ae5', 4, 'review', 'multiple_choice', 3, 'A study finds $r = 0.7$ between hours of TV and test anxiety. A valid conclusion is…', '{"choices":["TV causes anxiety","Anxiety causes TV watching","In this sample, more TV is associated with more anxiety","70% of anxiety is caused by TV"],"answer":2}', '[]', 'An association, not causation; and $r^2 = 0.49$, not 0.7, is the share of variation explained.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_1469596fc89ae5', 'subj_math', 'correlation', 'Correlation', 'A number r between −1 and 1 measuring the direction and strength of a linear relationship between two quantitative variables.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_1469596fc89ae5', (SELECT id FROM concepts WHERE slug = 'correlation'));

-- Lesson: describing-distributions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9aeeae30ed9951', 'describing-distributions', 'Describing shape, center and spread', 'Describe a quantitative distribution completely, covering shape, outliers, center and spread, always in the context of the data.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a6c8ca112ed079', 'les_9aeeae30ed9951', 1, 'Describe shape: symmetric, skewed left or right, unimodal or bimodal.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_aecc4d833f691f', 'les_9aeeae30ed9951', 2, 'Identify possible outliers and gaps.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_44ec5a18c80e3c', 'les_9aeeae30ed9951', 3, 'Report a center and spread that fit the shape, in context.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a6c8ca112ed079', 'les_9aeeae30ed9951', 'learn', 1, 'definition', '{"term":"A distribution","body":"The distribution of a variable tells what values it takes and how often. To describe one, address shape, outliers, center and spread, and name the variable and its units."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_aecc4d833f691f', 'les_9aeeae30ed9951', 'learn', 2, 'definition', '{"term":"Shape","body":"Symmetric: the two sides are near mirror images. Skewed right: a long tail toward larger values. Skewed left: a long tail toward smaller values. Unimodal or bimodal: one or two clear peaks."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_44ec5a18c80e3c', 'les_9aeeae30ed9951', 'learn', 3, 'definition', '{"term":"Matching center and spread to shape","body":"In a skewed distribution, the mean is pulled toward the tail, so report the median and IQR. For roughly symmetric distributions without outliers, the mean and standard deviation work well."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_457e02d4a5a51c', 'les_9aeeae30ed9951', 'learn', 4, 'worked_example', '{"title":"Commute times (minutes) for 25 workers: most between 10 and 30, a few at 50, 55 and 70","steps":[{"latex":"\\text{shape: skewed right}","explanation":"Long tail of long commutes."},{"latex":"\\text{outlier candidate: } 70","explanation":"Check with the 1.5 × IQR rule."},{"latex":"\\text{center and spread: median and IQR}","explanation":"Resistant to the tail."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_533b7c07a2d60c', 'les_9aeeae30ed9951', 'experiment', 5, 'activity', '{"activity":"data-explorer","title":"Shape, center and spread","params":{"dataset":"skewed","view":"histogram"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_669680c8c4dc50', 'les_9aeeae30ed9951', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"With the skewed data set, compare the mean and median. Then drag the largest values farther right: the mean moves, the median barely does."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_35b4c4653ee8d0', 'les_9aeeae30ed9951', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Income is skewed right, so governments report median household income; a few very high incomes would inflate the mean."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a6c8ca112ed079', 'les_9aeeae30ed9951', 1, 'practice', 'multiple_choice', 1, 'A distribution has a long tail to the right. It is…', '{"choices":["Skewed left","Skewed right","Symmetric","Bimodal"],"answer":1}', '[]', 'Skew is named for the direction of the tail.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_aecc4d833f691f', 'les_9aeeae30ed9951', 2, 'practice', 'multiple_choice', 2, 'In a strongly left-skewed distribution, the mean is usually…', '{"choices":["greater than the median","less than the median","equal to the median","unrelated to the median"],"answer":1}', '[]', 'The tail of small values pulls the mean down.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_44ec5a18c80e3c', 'les_9aeeae30ed9951', 3, 'practice', 'multiple_choice', 2, 'Heights of a mixed group of 7-year-olds and adults would most likely be…', '{"choices":["Unimodal and symmetric","Bimodal","Skewed right","Uniform"],"answer":1}', '[]', 'Two clusters, children and adults, give two peaks.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_457e02d4a5a51c', 'les_9aeeae30ed9951', 4, 'review', 'multiple_choice', 3, 'Which description is most complete?', '{"choices":["The data are skewed.","The median is 22.","Commute times are skewed right with a median of 22 minutes, IQR 12 minutes, and one high outlier at 70 minutes.","The data have a mean."],"answer":2}', '[]', 'It covers shape, center, spread and outliers, in context with units.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_0f43887800fc3d', 'subj_math', 'distributions', 'Distributions', 'The values a variable takes and how often it takes them.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9aeeae30ed9951', (SELECT id FROM concepts WHERE slug = 'distributions'));

-- Lesson: designing-experiments
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_200aabacf2dc4d', 'designing-experiments', 'Designing experiments', 'Design experiments using comparison, random assignment, control and replication; use placebos and blinding; and choose completely randomized, randomized block or matched pairs designs.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6b7f94f8bba4fd', 'les_200aabacf2dc4d', 1, 'Apply the four principles of experimental design.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_35edbbecc0a5b0', 'les_200aabacf2dc4d', 2, 'Explain the purpose of control groups, placebos and double-blinding.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_18ebaec5033f3f', 'les_200aabacf2dc4d', 3, 'Choose between completely randomized, block and matched pairs designs.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6b7f94f8bba4fd', 'les_200aabacf2dc4d', 'learn', 1, 'definition', '{"term":"Four principles","body":"Comparison: use at least two treatments (often including a control). Random assignment: use chance to assign units to treatments, so groups are similar except for the treatment. Control: keep other variables the same for all groups. Replication: use enough units in each group to see real differences."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_35edbbecc0a5b0', 'les_200aabacf2dc4d', 'learn', 2, 'definition', '{"term":"Placebo and blinding","body":"A placebo is a fake treatment; the placebo effect is a response to receiving any treatment. In a double-blind experiment neither the subjects nor those measuring the response know who got which treatment."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_18ebaec5033f3f', 'les_200aabacf2dc4d', 'learn', 3, 'definition', '{"term":"Blocking","body":"A block is a group of units similar in a way expected to affect the response. In a randomized block design, units are randomly assigned to treatments separately within each block. Matched pairs is a block design with blocks of size 2, or each subject receiving both treatments in random order."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a61aa7bb5b2a2b', 'les_200aabacf2dc4d', 'learn', 4, 'worked_example', '{"title":"Testing a new sunscreen on 40 volunteers","steps":[{"latex":"\\text{matched pairs: each volunteer gets the new sunscreen on one arm, the old on the other}","explanation":""},{"latex":"\\text{randomly choose which arm gets which}","explanation":"Controls for arm (dominant hand, sun exposure)."},{"latex":"\\text{compare redness on the two arms for each person}","explanation":"Differences within a person remove person-to-person variation."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ad01e7445b824e', 'les_200aabacf2dc4d', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"New medicines are approved after randomized, double-blind, placebo-controlled trials, the strongest design for showing cause and effect."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6b7f94f8bba4fd', 'les_200aabacf2dc4d', 1, 'practice', 'multiple_choice', 1, 'What is the main purpose of random assignment?', '{"choices":["To make the sample represent the population","To create groups that are similar except for the treatment","To make the experiment cheaper","To blind the subjects"],"answer":1}', '[]', 'Random assignment balances other variables across groups, allowing causal conclusions.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_35edbbecc0a5b0', 'les_200aabacf2dc4d', 2, 'practice', 'multiple_choice', 2, 'A fertilizer study uses fields in two very different soil types. A good design would…', '{"choices":["Ignore soil","Block by soil type and randomize within each block","Use only one field","Let farmers choose"],"answer":1}', '[]', 'Blocking removes the variation due to soil.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_18ebaec5033f3f', 'les_200aabacf2dc4d', 3, 'practice', 'multiple_choice', 2, 'In a double-blind experiment…', '{"choices":["Subjects know their treatment","Neither subjects nor evaluators know who got which treatment","There are two treatments","Two researchers run it"],"answer":1}', '[]', 'That prevents expectations from affecting responses or measurements.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a61aa7bb5b2a2b', 'les_200aabacf2dc4d', 4, 'review', 'multiple_choice', 3, 'Random sampling vs random assignment: which lets you generalize to a population, and which lets you conclude cause and effect?', '{"choices":["Sampling: generalize; assignment: cause","Sampling: cause; assignment: generalize","Both give both","Neither"],"answer":0}', '[]', 'Random sampling supports generalization; random assignment supports causation.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_8954756507bcfa', 'subj_math', 'study-design', 'Study design', 'How data are produced (sample surveys, observational studies, experiments) and what conclusions each design supports.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_200aabacf2dc4d', (SELECT id FROM concepts WHERE slug = 'study-design'));

-- Lesson: equivalent-representations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0a9b9a7d819539', 'equivalent-representations', 'Equivalent representations of polynomial and rational expressions', 'Rewrite polynomial and rational expressions in standard, factored and quotient-plus-remainder forms, and choose the form that reveals what you need.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fdc0c7255fe85a', 'les_0a9b9a7d819539', 1, 'Choose standard or factored form to reveal end behavior, intercepts or zeros.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_81d23fc172294c', 'les_0a9b9a7d819539', 2, 'Use polynomial division to rewrite a rational expression as quotient plus remainder over divisor.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ad7fa920971995', 'les_0a9b9a7d819539', 3, 'Use the Binomial Theorem to expand powers of binomials.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fdc0c7255fe85a', 'les_0a9b9a7d819539', 'learn', 1, 'definition', '{"term":"Which form shows what","body":"Standard form shows the degree, leading coefficient and $y$-intercept. Factored form shows zeros and their multiplicities. For a rational expression, the form $q(x) + \\frac{r(x)}{d(x)}$ shows the end behavior through the quotient $q$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_81d23fc172294c', 'les_0a9b9a7d819539', 'learn', 2, 'worked_example', '{"title":"$f(x) = 2x^3 - 8x$","steps":[{"latex":"f(x) = 2x(x - 2)(x + 2)","explanation":"Factored: zeros at 0, 2 and −2."},{"latex":"\\text{leading term } 2x^3","explanation":"Standard: rises to the right, falls to the left."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ad7fa920971995', 'les_0a9b9a7d819539', 'learn', 3, 'worked_example', '{"title":"Rewrite $\\dfrac{x^3 - 2x^2 + 4}{x - 2}$","steps":[{"latex":"x^3 - 2x^2 = x^2(x - 2)","explanation":""},{"latex":"\\frac{x^3 - 2x^2 + 4}{x - 2} = x^2 + \\frac{4}{x - 2}","explanation":"For large |x| it behaves like the parabola y = x²."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_37de2dc7cef0be', 'les_0a9b9a7d819539', 'learn', 4, 'worked_example', '{"title":"Expand $(x + 2)^4$ with the Binomial Theorem","steps":[{"latex":"\\binom{4}{0}x^4 + \\binom{4}{1}x^3 \\cdot 2 + \\binom{4}{2}x^2 \\cdot 4 + \\binom{4}{3}x \\cdot 8 + 16","explanation":"Coefficients 1, 4, 6, 4, 1."},{"latex":"x^4 + 8x^3 + 24x^2 + 32x + 16","explanation":""}],"check":"Check at $x = 1$: $3^4 = 81$ and $1 + 8 + 24 + 32 + 16 = 81$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a4a779dd9f5218', 'les_0a9b9a7d819539', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Engineers rewrite transfer functions as quotient plus remainder to separate long-run behavior from short-lived effects."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fdc0c7255fe85a', 'les_0a9b9a7d819539', 1, 'practice', 'numeric', 1, 'In the expansion of $(x + 1)^3$, what is the coefficient of $x$?', '{"answer":3}', '["Row 1, 3, 3, 1 of Pascal''s triangle."]', '$x^3 + 3x^2 + 3x + 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_81d23fc172294c', 'les_0a9b9a7d819539', 2, 'practice', 'multiple_choice', 2, '$\dfrac{2x^2 + 3x - 5}{x - 1}$ simplifies to…', '{"choices":["$2x + 5$, for $x \\ne 1$","$2x - 5$","$2x + 1 + \\frac{4}{x - 1}$","$2x^2 + 5$"],"answer":0}', '["Try factoring the numerator."]', '$2x^2 + 3x - 5 = (2x + 5)(x - 1)$, so the quotient is $2x + 5$ with a hole at $x = 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ad7fa920971995', 'les_0a9b9a7d819539', 3, 'practice', 'multiple_choice', 2, 'Which form of $f(x) = x^2 - 6x + 8$ shows its zeros directly?', '{"choices":["$x^2 - 6x + 8$","$(x - 3)^2 - 1$","$(x - 2)(x - 4)$","$x(x - 6) + 8$"],"answer":2}', '[]', 'Factored form: zeros 2 and 4. (Vertex form shows the vertex (3, −1).)');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_37de2dc7cef0be', 'les_0a9b9a7d819539', 4, 'review', 'numeric', 3, 'In the expansion of $(x - 3)^4$, what is the coefficient of $x^2$?', '{"answer":54}', '["$\\binom{4}{2}x^2(-3)^2$."]', '$6 \cdot 9 = 54$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0a9b9a7d819539', (SELECT id FROM concepts WHERE slug = 'polynomials'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0a9b9a7d819539', (SELECT id FROM concepts WHERE slug = 'rational-functions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_0a9b9a7d819539', (SELECT id FROM formulas WHERE slug = 'binomial-theorem'), 1);

-- Lesson: errors-and-power
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_baa5fe7c2a12aa', 'errors-and-power', 'Errors and power in significance tests', 'Describe Type I and Type II errors and their consequences in context, connect α to the Type I error rate, and explain what increases the power of a test.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7992da1a806a85', 'les_baa5fe7c2a12aa', 1, 'Define Type I and Type II errors and describe each in context.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_33ad822f0d257b', 'les_baa5fe7c2a12aa', 2, 'Recognize that P(Type I error) = α when H₀ is true.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e262e58e7e4c4f', 'les_baa5fe7c2a12aa', 3, 'Explain how sample size, α and effect size affect power.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7992da1a806a85', 'les_baa5fe7c2a12aa', 'learn', 1, 'definition', '{"term":"Type I and Type II errors","body":"Type I error: rejecting $H_0$ when it''s true (a false alarm). Type II error: failing to reject $H_0$ when $H_a$ is true (a missed effect). If $H_0$ is true, the probability of a Type I error is $\\alpha$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_33ad822f0d257b', 'les_baa5fe7c2a12aa', 'learn', 2, 'definition', '{"term":"Power","body":"Power is the probability that the test correctly rejects $H_0$ when a specific alternative is true: power $= 1 - P(\\text{Type II error})$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e262e58e7e4c4f', 'les_baa5fe7c2a12aa', 'learn', 3, 'worked_example', '{"title":"A factory tests $H_0$: the machine is working correctly, vs $H_a$: it''s out of calibration.","steps":[{"latex":"\\text{Type I: stop a working machine}","explanation":"Cost: lost production."},{"latex":"\\text{Type II: keep running a faulty machine}","explanation":"Cost: defective products shipped."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3c7966d8bede6e', 'les_baa5fe7c2a12aa', 'learn', 4, 'definition', '{"term":"Increasing power","body":"Power goes up with a larger sample size, a larger $\\alpha$ (at the cost of more Type I errors), a larger true effect (the farther the truth is from $H_0$), and less variability in the data."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4aa90af3bf2f7d', 'les_baa5fe7c2a12aa', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Clinical trials are planned with a target power, often 80% or 90%, by choosing enough patients to detect the smallest effect that would matter medically."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7992da1a806a85', 'les_baa5fe7c2a12aa', 1, 'practice', 'multiple_choice', 1, 'A Type I error is…', '{"choices":["Failing to reject a false H₀","Rejecting a true H₀","Using the wrong test","A calculation mistake"],"answer":1}', '[]', 'A false alarm.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_33ad822f0d257b', 'les_baa5fe7c2a12aa', 2, 'practice', 'multiple_choice', 2, 'A medical test checks $H_0$: no disease. A Type II error means…', '{"choices":["A healthy person is told they have the disease","A sick person is told they''re healthy","The test is too expensive","The result is correct"],"answer":1}', '[]', 'Failing to reject $H_0$ when the disease is present.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e262e58e7e4c4f', 'les_baa5fe7c2a12aa', 3, 'practice', 'multiple_choice', 2, 'Which change increases power without changing α?', '{"choices":["Decreasing n","Increasing n","Using a two-sided test instead of one-sided","Rounding the data"],"answer":1}', '[]', 'A larger sample makes the sampling distribution narrower, so real effects stand out.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3c7966d8bede6e', 'les_baa5fe7c2a12aa', 4, 'review', 'multiple_choice', 3, 'Lowering α from 0.05 to 0.01 does what to the chance of a Type II error?', '{"choices":["Decreases it","Increases it","No effect","Makes it zero"],"answer":1}', '[]', 'A stricter standard makes rejecting harder, so more real effects are missed.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d1e1e71a856b16', 'subj_math', 'significance-tests', 'Significance tests', 'Procedures that use sample data to weigh evidence against a claim about a population parameter.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_baa5fe7c2a12aa', (SELECT id FROM concepts WHERE slug = 'significance-tests'));

-- Lesson: expected-value-random-variables
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_8d2e31768f5c55', 'expected-value-random-variables', 'Expected value and spread of a random variable', 'Describe discrete random variables with probability distributions, and compute and interpret their mean (expected value) and standard deviation.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_75801ed085c509', 'les_8d2e31768f5c55', 1, 'Write a valid probability distribution for a discrete random variable.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_cb7c83e83dc28b', 'les_8d2e31768f5c55', 2, 'Compute and interpret the expected value μ_X.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_af213654e90c26', 'les_8d2e31768f5c55', 3, 'Compute and interpret the standard deviation σ_X.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_75801ed085c509', 'les_8d2e31768f5c55', 'learn', 1, 'definition', '{"term":"Random variable","body":"A random variable $X$ takes numerical values that describe the outcomes of a random process. A discrete random variable has a list of possible values, each with a probability; the probabilities are between 0 and 1 and add to 1."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cb7c83e83dc28b', 'les_8d2e31768f5c55', 'learn', 2, 'definition', '{"term":"Expected value","body":"$\\mu_X = \\sum x_i p_i$: the long-run average of $X$ over many repetitions. It need not be a possible value of $X$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_af213654e90c26', 'les_8d2e31768f5c55', 'learn', 3, 'worked_example', '{"title":"A 5-dollar raffle ticket wins 100 dollars with probability 0.02 and 20 dollars with probability 0.05. What is the expected net gain?","steps":[{"latex":"E(\\text{prize}) = 100(0.02) + 20(0.05) + 0(0.93) = 3","explanation":""},{"latex":"E(\\text{net}) = 3 - 5 = -2","explanation":"On average a buyer loses 2 dollars per ticket."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e425170a01b53a', 'les_8d2e31768f5c55', 'learn', 4, 'worked_example', '{"title":"$X$ = number of heads in 2 coin flips: values 0, 1, 2 with probabilities 0.25, 0.5, 0.25","steps":[{"latex":"\\mu_X = 0 + 0.5 + 0.5 = 1","explanation":""},{"latex":"\\sigma_X^2 = (0 - 1)^2(0.25) + 0 + (2 - 1)^2(0.25) = 0.5","explanation":""},{"latex":"\\sigma_X = \\sqrt{0.5} \\approx 0.707","explanation":"Typical distance from the mean of 1 head."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7f80bdf843a4b4', 'les_8d2e31768f5c55', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Insurance premiums and casino games are priced from expected values: the insurer''s expected payout per policy is less than the premium, which is how the business stays solvent."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_75801ed085c509', 'les_8d2e31768f5c55', 1, 'practice', 'numeric', 1, '$X$ takes values 1, 2, 3 with probabilities 0.2, 0.5, 0.3. Find $\mu_X$.', '{"answer":2.1,"tolerance":0.001}', '[]', '$0.2 + 1.0 + 0.9 = 2.1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cb7c83e83dc28b', 'les_8d2e31768f5c55', 2, 'practice', 'numeric', 2, '$X$ takes values 0 and 10, each with probability 0.5. Find $\sigma_X$.', '{"answer":5,"tolerance":0.001}', '["$\\mu_X = 5$."]', '$\sigma_X^2 = 25(0.5) + 25(0.5) = 25$, $\sigma_X = 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_af213654e90c26', 'les_8d2e31768f5c55', 3, 'practice', 'multiple_choice', 2, 'Which is a valid probability distribution?', '{"choices":["0.3, 0.3, 0.3","0.5, 0.6, −0.1","0.2, 0.3, 0.5","0.4, 0.4, 0.4"],"answer":2}', '[]', 'Probabilities must be between 0 and 1 and sum to 1.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e425170a01b53a', 'les_8d2e31768f5c55', 4, 'review', 'numeric', 3, 'A game costs 2 dollars. You win 10 dollars with probability 0.15, otherwise nothing. What is your expected net gain per game, in dollars?', '{"answer":-0.5,"tolerance":0.001,"unit":"dollars"}', '[]', '$10(0.15) - 2 = -0.5$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_edd54efaadfef2', 'subj_math', 'random-variables', 'Random variables', 'Numerical outcomes of random processes, described by probability distributions with a mean and standard deviation.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_8d2e31768f5c55', (SELECT id FROM concepts WHERE slug = 'random-variables'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_8d2e31768f5c55', (SELECT id FROM formulas WHERE slug = 'expected-value'), 1);

-- Lesson: exponential-data-modeling
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_dd5d6bca452b9f', 'exponential-data-modeling', 'Exponential function context and data modeling', 'Recognize exponential data from constant ratios, build growth and decay models from two points or a half-life, and interpret the parameters in context.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d7ac08c8ebb105', 'les_dd5d6bca452b9f', 1, 'Test data for an exponential pattern using successive ratios.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3e605d022bd431', 'les_dd5d6bca452b9f', 2, 'Build models from an initial value and a growth factor, a percent rate, or a doubling time or half-life.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_155025d8aaa9b4', 'les_dd5d6bca452b9f', 3, 'Interpret a and b in context and use the model to predict.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d7ac08c8ebb105', 'les_dd5d6bca452b9f', 'learn', 1, 'definition', '{"term":"Exponential data","body":"If equally spaced inputs give outputs with a (roughly) constant ratio, an exponential model $y = a b^x$ fits. Here $a$ is the initial value and $b$ the growth factor per unit; $b = 1 + r$ for a percent rate $r$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3e605d022bd431', 'les_dd5d6bca452b9f', 'learn', 2, 'worked_example', '{"title":"A culture has 200 cells at $t = 0$ h and 450 at $t = 2$ h. Model and predict $t = 5$.","steps":[{"latex":"200b^2 = 450,\\ b^2 = 2.25,\\ b = 1.5","explanation":"50% growth per hour."},{"latex":"N(t) = 200 \\cdot 1.5^t","explanation":""},{"latex":"N(5) = 200 \\cdot 7.59375 \\approx 1519","explanation":"cells"}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_155025d8aaa9b4', 'les_dd5d6bca452b9f', 'learn', 3, 'worked_example', '{"title":"A drug dose of 80 mg has a half-life of 6 h. How much remains after 15 h?","steps":[{"latex":"A(t) = 80\\left(\\tfrac{1}{2}\\right)^{t/6}","explanation":""},{"latex":"A(15) = 80 \\cdot 0.5^{2.5} \\approx 14.1","explanation":"mg"}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_53ed14bfbd3278', 'les_dd5d6bca452b9f', 'experiment', 4, 'activity', '{"activity":"growth-models","title":"Constant factor, step by step","params":{"a":2,"b":1.5,"d":3,"compare":true}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_654ff29f225d61', 'les_dd5d6bca452b9f', 'learn', 5, 'callout', '{"tone":"tip","title":"Check the ratio","body":"Compute successive ratios $y_{n+1}/y_n$. Real data won''t give identical ratios; roughly constant is the signal. Then a regression (on a calculator or by fitting $\\ln y$ against $x$ with a line) gives the best $a$ and $b$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8553a0c9fb2949', 'les_dd5d6bca452b9f', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Compound interest, viral spread in early outbreaks, radioactive dating and cooling (as a difference from room temperature) all use exponential models."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d7ac08c8ebb105', 'les_dd5d6bca452b9f', 1, 'practice', 'multiple_choice', 1, 'Outputs 5, 15, 45, 135 at $x = 0, 1, 2, 3$. What is the growth factor?', '{"choices":["3","10","5","1.5"],"answer":0}', '[]', 'Each output is 3 times the last.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3e605d022bd431', 'les_dd5d6bca452b9f', 2, 'practice', 'numeric', 2, '1000 dollars grows at 4% per year: $1000(1.04)^t$. Find the value after 10 years, to the nearest dollar.', '{"answer":1480,"tolerance":1,"unit":"dollars"}', '[]', '$1000 \cdot 1.04^{10} \approx 1480.24$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_155025d8aaa9b4', 'les_dd5d6bca452b9f', 3, 'practice', 'numeric', 2, 'A town of 12,000 shrinks by 3% per year. What is the decay factor $b$?', '{"answer":0.97,"tolerance":0.0001}', '[]', '$1 - 0.03 = 0.97$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_53ed14bfbd3278', 'les_dd5d6bca452b9f', 4, 'practice', 'numeric', 3, 'A substance has a half-life of 10 years. What fraction remains after 30 years? Give a decimal.', '{"answer":0.125,"tolerance":0.0001}', '[]', '$(1/2)^3 = 0.125$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_654ff29f225d61', 'les_dd5d6bca452b9f', 5, 'review', 'multiple_choice', 3, 'In $P(t) = 850(1.12)^t$, what does 850 represent?', '{"choices":["The growth rate","The population when t = 0","The population after 12 years","The maximum population"],"answer":1}', '[]', '$P(0) = 850$, the initial value.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_dd5d6bca452b9f', (SELECT id FROM concepts WHERE slug = 'exponential-functions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_dd5d6bca452b9f', (SELECT id FROM formulas WHERE slug = 'exponential-function'), 1);

-- Lesson: function-model-construction
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_e03a6781aa515b', 'function-model-construction', 'Function model construction and application', 'Build linear, quadratic, exponential and piecewise models from data points or a context, use them to predict, and judge predictions with residuals.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4623fd4d6ce038', 'les_e03a6781aa515b', 1, 'Construct a model through given points by solving for its parameters.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d03a17c349e83a', 'les_e03a6781aa515b', 2, 'Build piecewise models when a context changes rules.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ff09619fc8dd28', 'les_e03a6781aa515b', 3, 'Use residuals to judge how well a model fits and when predictions are reasonable.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4623fd4d6ce038', 'les_e03a6781aa515b', 'learn', 1, 'definition', '{"term":"Constructing a model","body":"Pick a function type, then use known points (or a regression on many points) to find its parameters. A model with $n$ parameters needs at least $n$ points to pin down exactly."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d03a17c349e83a', 'les_e03a6781aa515b', 'learn', 2, 'worked_example', '{"title":"Quadratic through $(0, 2)$, $(1, 5)$ and $(2, 12)$","steps":[{"latex":"c = 2","explanation":"From (0, 2)."},{"latex":"a + b = 3,\\ 4a + 2b = 10","explanation":"Substitute the other points."},{"latex":"a = 2,\\ b = 1:\\ y = 2x^2 + x + 2","explanation":""}],"check":"Check $x = 2$: $8 + 2 + 2 = 12$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ff09619fc8dd28', 'les_e03a6781aa515b', 'learn', 3, 'worked_example', '{"title":"Exponential through $(0, 50)$ and $(3, 400)$","steps":[{"latex":"a = 50,\\ 50b^3 = 400","explanation":""},{"latex":"b^3 = 8,\\ b = 2:\\ y = 50 \\cdot 2^x","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c4417ae5568be6', 'les_e03a6781aa515b', 'learn', 4, 'worked_example', '{"title":"A phone plan: 30 dollars for up to 5 GB, then 10 dollars per extra GB","steps":[{"latex":"C(g) = \\begin{cases} 30 & 0 \\le g \\le 5 \\\\ 30 + 10(g - 5) & g > 5 \\end{cases}","explanation":"Piecewise model."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_41cc9c3d95a4ae', 'les_e03a6781aa515b', 'learn', 5, 'definition', '{"term":"Residuals","body":"A residual is actual minus predicted. Small residuals with no pattern suggest a good fit; a curved pattern suggests the wrong function type."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2d12edfb6cd435', 'les_e03a6781aa515b', 'learn', 6, 'callout', '{"tone":"warning","title":"Extrapolation","body":"Predictions far outside the data range are risky: the pattern may not continue."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9c7589a91d2d8c', 'les_e03a6781aa515b', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Epidemiologists fit models to early case counts, then check residuals each week to see whether the model still fits."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4623fd4d6ce038', 'les_e03a6781aa515b', 1, 'practice', 'numeric', 1, 'A linear model passes through $(2, 7)$ and $(6, 19)$. What does it predict at $x = 10$?', '{"answer":31}', '["Slope (19 − 7)/(6 − 2)."]', 'Slope 3; $y = 3x + 1$; $3(10) + 1 = 31$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d03a17c349e83a', 'les_e03a6781aa515b', 2, 'practice', 'numeric', 2, 'A model predicts 12.5 and the actual value is 14. What is the residual?', '{"answer":1.5,"tolerance":0.001}', '[]', '$14 - 12.5 = 1.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ff09619fc8dd28', 'les_e03a6781aa515b', 3, 'practice', 'numeric', 2, 'An exponential model $y = ab^x$ passes through $(0, 3)$ and $(2, 75)$ with $b > 0$. Find $b$.', '{"answer":5}', '[]', '$3b^2 = 75$, $b^2 = 25$, $b = 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c4417ae5568be6', 'les_e03a6781aa515b', 4, 'practice', 'numeric', 2, 'Using the phone plan above, what does 8 GB cost, in dollars?', '{"answer":60,"unit":"dollars"}', '[]', '$30 + 10(3) = 60$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_41cc9c3d95a4ae', 'les_e03a6781aa515b', 5, 'review', 'multiple_choice', 3, 'Residuals from a linear model are positive at both ends of the data and negative in the middle. What does that suggest?', '{"choices":["The linear model fits well","A curved model, such as a quadratic, would fit better","The data have no pattern","The slope is wrong but the type is right"],"answer":1}', '[]', 'A U-shaped residual pattern means the data curve upward away from the line.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_e03a6781aa515b', (SELECT id FROM concepts WHERE slug = 'function-families'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_e03a6781aa515b', (SELECT id FROM concepts WHERE slug = 'linear-models'));

-- Lesson: geometric-distributions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_c2acc78f601eb7', 'geometric-distributions', 'Geometric distributions', 'Model the number of trials until the first success, compute geometric probabilities, and find the mean number of trials.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7fdc5ac7fe3fa7', 'les_c2acc78f601eb7', 1, 'Recognize geometric settings: independent trials with the same p, counting trials until the first success.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6ccfaac4c18873', 'les_c2acc78f601eb7', 2, 'Compute P(X = k) = (1 − p)^(k − 1)·p and P(X > k) = (1 − p)^k.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_30fb58902e1a14', 'les_c2acc78f601eb7', 3, 'Interpret the mean 1/p.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7fdc5ac7fe3fa7', 'les_c2acc78f601eb7', 'learn', 1, 'definition', '{"term":"Geometric setting","body":"Independent trials, each a success or failure with the same probability $p$; $X$ counts the trials up to and including the first success. Possible values: 1, 2, 3, …"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6ccfaac4c18873', 'les_c2acc78f601eb7', 'learn', 2, 'definition', '{"term":"Formulas","body":"$P(X = k) = (1 - p)^{k - 1}p$; $P(X > k) = (1 - p)^k$ (the first $k$ trials all fail); $\\mu_X = \\frac{1}{p}$; $\\sigma_X = \\frac{\\sqrt{1 - p}}{p}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_30fb58902e1a14', 'les_c2acc78f601eb7', 'learn', 3, 'worked_example', '{"title":"Roll a fair die until a 6 appears. Find $P(\\text{first 6 on roll 3})$ and the mean.","steps":[{"latex":"\\left(\\tfrac{5}{6}\\right)^2 \\cdot \\tfrac{1}{6} = \\tfrac{25}{216} \\approx 0.116","explanation":""},{"latex":"\\mu = \\frac{1}{1/6} = 6 \\text{ rolls}","explanation":"On average it takes 6 rolls."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7c93023097bdbc', 'les_c2acc78f601eb7', 'learn', 4, 'callout', '{"tone":"tip","title":"The distribution is always skewed right","body":"$P(X = 1) = p$ is the most likely single value, and each later probability is $(1 - p)$ times the one before."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dcc81926a909a9', 'les_c2acc78f601eb7', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Sales calls until the first sale, attempts until a network connection succeeds, and screenings until finding a matching donor are geometric."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7fdc5ac7fe3fa7', 'les_c2acc78f601eb7', 1, 'practice', 'numeric', 1, '$p = 0.2$. Find $P(X = 2)$.', '{"answer":0.16,"tolerance":0.001}', '[]', '$0.8 \cdot 0.2 = 0.16$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6ccfaac4c18873', 'les_c2acc78f601eb7', 2, 'practice', 'numeric', 1, '$p = 0.25$. Find the mean number of trials to the first success.', '{"answer":4}', '[]', '$\frac{1}{0.25} = 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_30fb58902e1a14', 'les_c2acc78f601eb7', 3, 'practice', 'numeric', 2, 'Flip a fair coin until heads. Find $P(\text{more than 3 flips are needed})$.', '{"answer":0.125,"tolerance":0.001}', '[]', '$0.5^3 = 0.125$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7c93023097bdbc', 'les_c2acc78f601eb7', 4, 'review', 'multiple_choice', 3, 'Which is a geometric setting?', '{"choices":["Number of heads in 10 flips","Number of cards drawn without replacement until an ace, from one deck","Number of free throws until the first miss, for a 70% shooter with independent shots","Number of girls in a family of 4"],"answer":2}', '[]', 'Independent trials, constant $p$ = 0.3 of a miss, counting to the first "success."');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_edd54efaadfef2', 'subj_math', 'random-variables', 'Random variables', 'Numerical outcomes of random processes, described by probability distributions with a mean and standard deviation.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_c2acc78f601eb7', (SELECT id FROM concepts WHERE slug = 'random-variables'));

-- Lesson: least-squares-regression
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_fe54b32d62a284', 'least-squares-regression', 'Least-squares regression lines', 'Find the least-squares regression line from summary statistics or data, interpret its slope and intercept in context, and use it to predict.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_225e8fc0f52e41', 'les_fe54b32d62a284', 1, 'Explain what ''least squares'' means.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_95fc1c8d2a9d91', 'les_fe54b32d62a284', 2, 'Compute b = r·s_y/s_x and a = ȳ − b·x̄.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_67aa7a40748288', 'les_fe54b32d62a284', 3, 'Interpret slope and y-intercept in context, and avoid extrapolation.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_225e8fc0f52e41', 'les_fe54b32d62a284', 'learn', 1, 'definition', '{"term":"Least squares","body":"Of all lines, the least-squares regression line makes the sum of squared vertical distances (residuals) from the points to the line as small as possible. It''s written $\\hat{y} = a + bx$, where $\\hat{y}$ is the predicted response."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_95fc1c8d2a9d91', 'les_fe54b32d62a284', 'learn', 2, 'formula', '{"latex":"b = r\\frac{s_y}{s_x}, \\qquad a = \\bar{y} - b\\bar{x}","title":"Slope and intercept from summary statistics","note":"The line always passes through the point (x̄, ȳ)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_67aa7a40748288', 'les_fe54b32d62a284', 'learn', 3, 'worked_example', '{"title":"Data $x$: 1, 2, 3, 4, 5 and $y$: 2, 4, 5, 4, 5 (from the correlation lesson)","steps":[{"latex":"b = \\frac{\\sum (x - \\bar{x})(y - \\bar{y})}{\\sum (x - \\bar{x})^2} = \\frac{6}{10} = 0.6","explanation":"Same as r · s_y / s_x."},{"latex":"a = 4 - 0.6(3) = 2.2","explanation":""},{"latex":"\\hat{y} = 2.2 + 0.6x","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_707b09b27ccd5d', 'les_fe54b32d62a284', 'learn', 4, 'worked_example', '{"title":"Interpret a model $\\widehat{\\text{price}} = 15{,}000 + 120(\\text{square meters})$","steps":[{"latex":"b = 120","explanation":"Predicted price rises by 120 dollars for each extra square meter, on average."},{"latex":"a = 15{,}000","explanation":"Predicted price of a 0 m² home: not meaningful (extrapolation)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dfb3ef21ce7d9a', 'les_fe54b32d62a284', 'learn', 5, 'callout', '{"tone":"warning","title":"Extrapolation","body":"Predicting far outside the range of the $x$ data is unreliable; the linear pattern may not continue."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1a0fb45ea83ae4', 'les_fe54b32d62a284', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Regression is how analysts estimate the effect of one variable on another: price per square meter, calories burned per minute, or yield per unit of fertilizer."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_225e8fc0f52e41', 'les_fe54b32d62a284', 1, 'practice', 'numeric', 2, '$r = 0.8$, $s_x = 2$, $s_y = 5$. Find the slope $b$.', '{"answer":2}', '[]', '$0.8 \cdot \frac{5}{2} = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_95fc1c8d2a9d91', 'les_fe54b32d62a284', 2, 'practice', 'numeric', 2, 'With that slope, $\bar{x} = 10$ and $\bar{y} = 30$, find the intercept $a$.', '{"answer":10}', '[]', '$30 - 2(10) = 10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_67aa7a40748288', 'les_fe54b32d62a284', 3, 'practice', 'numeric', 2, 'Predict $y$ at $x = 12$ using $\hat{y} = 10 + 2x$.', '{"answer":34}', '[]', '$10 + 24 = 34$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_707b09b27ccd5d', 'les_fe54b32d62a284', 4, 'review', 'multiple_choice', 3, 'In $\widehat{\text{score}} = 52 + 4.5(\text{hours studied})$, the slope means…', '{"choices":["Each student scores 4.5","Predicted score rises 4.5 points per additional hour studied","Score rises 52 points per hour","Studying causes 4.5 more points"],"answer":1}', '[]', 'Slope is the predicted change in $y$ per unit increase in $x$; it describes an association, not proven causation.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_ea585073ff8843', 'subj_math', 'regression', 'Linear regression', 'Fitting the least-squares line ŷ = a + bx to predict a response variable from an explanatory variable.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_fe54b32d62a284', (SELECT id FROM concepts WHERE slug = 'regression'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_1469596fc89ae5', 'subj_math', 'correlation', 'Correlation', 'A number r between −1 and 1 measuring the direction and strength of a linear relationship between two quantitative variables.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_fe54b32d62a284', (SELECT id FROM concepts WHERE slug = 'correlation'));
