-- Lesson: log-data-modeling
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_62e8c22711e930', 'log-data-modeling', 'Logarithmic function context and data modeling', 'Recognize logarithmic data (equal output increases over equal input factors), build log models, and use logarithmic scales such as pH and earthquake magnitude.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ea07242c09d75b', 'les_62e8c22711e930', 1, 'Identify logarithmic patterns in data: inputs multiply while outputs add.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_af38705ba3f1e0', 'les_62e8c22711e930', 2, 'Build a model of the form y = a + b log x or y = a + b ln x.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bafd52f3713d3e', 'les_62e8c22711e930', 3, 'Interpret logarithmic scales in science contexts.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ea07242c09d75b', 'les_62e8c22711e930', 'learn', 1, 'definition', '{"term":"Logarithmic data","body":"If multiplying the input by a constant factor adds a constant amount to the output, a logarithmic model $y = a + b\\log x$ fits. Logarithmic models rise quickly at first and then ever more slowly, without a bound."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_af38705ba3f1e0', 'les_62e8c22711e930', 'learn', 2, 'worked_example', '{"title":"$x$: 1, 10, 100, 1000 and $y$: 2, 5, 8, 11","steps":[{"latex":"\\times 10 \\text{ in } x \\Rightarrow +3 \\text{ in } y","explanation":"Log pattern."},{"latex":"y = 2 + 3\\log x","explanation":"At $x = 1$, $\\log 1 = 0$, so $a = 2$."},{"latex":"y(10^4) = 2 + 3 \\cdot 4 = 14","explanation":"Prediction."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bafd52f3713d3e', 'les_62e8c22711e930', 'learn', 3, 'worked_example', '{"title":"pH $= -\\log[\\mathrm{H^+}]$. Find the pH when $[\\mathrm{H^+}] = 2.5 \\times 10^{-5}$.","steps":[{"latex":"-\\log(2.5) - \\log(10^{-5}) = -0.398 + 5","explanation":""},{"latex":"\\text{pH} \\approx 4.60","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_13f3dfc7e7d760', 'les_62e8c22711e930', 'experiment', 4, 'activity', '{"activity":"exp-log","title":"The log grows slowly","params":{"b":3}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_381dadbf780e21', 'les_62e8c22711e930', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Earthquake magnitude, decibels and pH are logarithmic: each 1-unit step on the Richter scale is a 10-fold change in measured wave amplitude, and each 10 dB step is a 10-fold change in sound intensity."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ea07242c09d75b', 'les_62e8c22711e930', 1, 'practice', 'numeric', 1, 'Find the pH of a solution with $[\mathrm{H^+}] = 10^{-3}$.', '{"answer":3}', '[]', '$-\log 10^{-3} = 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_af38705ba3f1e0', 'les_62e8c22711e930', 2, 'practice', 'numeric', 2, 'Using $y = 2 + 3\log x$, find $y$ when $x = 100{,}000$.', '{"answer":17}', '[]', '$\log 10^5 = 5$, so $y = 17$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bafd52f3713d3e', 'les_62e8c22711e930', 3, 'practice', 'numeric', 2, 'Two earthquakes differ by 2 on the Richter scale. How many times larger is the wave amplitude of the larger one?', '{"answer":100}', '[]', '$10^2 = 100$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_13f3dfc7e7d760', 'les_62e8c22711e930', 4, 'review', 'multiple_choice', 3, 'Which data set is best modeled by a logarithmic function?', '{"choices":["x: 1, 2, 3, 4; y: 3, 6, 12, 24","x: 1, 2, 4, 8; y: 5, 7, 9, 11","x: 1, 2, 3, 4; y: 1, 4, 9, 16","x: 1, 2, 3, 4; y: 2, 4, 6, 8"],"answer":1}', '["Look for inputs that multiply while outputs add."]', 'Doubling $x$ adds 2 to $y$: $y = 5 + 2\log_2 x$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_62e8c22711e930', (SELECT id FROM concepts WHERE slug = 'logarithms'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_62e8c22711e930', (SELECT id FROM formulas WHERE slug = 'log-properties'), 1);

-- Lesson: observational-studies-experiments
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a32f2e9c0e9fc9', 'observational-studies-experiments', 'Observational studies and experiments', 'Distinguish observational studies from experiments, identify explanatory and response variables, and explain how confounding prevents cause-and-effect conclusions from observational data.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a08fb9fef9c79f', 'les_a32f2e9c0e9fc9', 1, 'Tell whether a study is observational or an experiment.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8051e56a1f702b', 'les_a32f2e9c0e9fc9', 2, 'Identify explanatory and response variables.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_68e1f097674f77', 'les_a32f2e9c0e9fc9', 3, 'Explain confounding and why only randomized experiments can show causation.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a08fb9fef9c79f', 'les_a32f2e9c0e9fc9', 'learn', 1, 'definition', '{"term":"Observational study vs experiment","body":"An observational study measures variables without trying to influence the responses. An experiment deliberately imposes treatments on individuals to measure their responses."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8051e56a1f702b', 'les_a32f2e9c0e9fc9', 'learn', 2, 'definition', '{"term":"Explanatory and response variables","body":"The explanatory variable may help explain or predict changes in the response variable. In an experiment, the treatments are values of the explanatory variable."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_68e1f097674f77', 'les_a32f2e9c0e9fc9', 'learn', 3, 'definition', '{"term":"Confounding","body":"Two variables are confounded when their effects on the response can''t be separated. In observational studies, people choose their own \"treatments,\" and their choices are often linked to other variables."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f7eb6e14a2b784', 'les_a32f2e9c0e9fc9', 'learn', 4, 'worked_example', '{"title":"A study of 5,000 adults finds that those who take vitamins have fewer heart attacks.","steps":[{"latex":"\\text{observational: people chose whether to take vitamins}","explanation":""},{"latex":"\\text{possible confounders: diet, exercise, income}","explanation":"Vitamin takers may live healthier lives overall."},{"latex":"\\text{conclusion: association only}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c071192d95394a', 'les_a32f2e9c0e9fc9', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Early observational studies suggested hormone therapy protected women''s hearts; a large randomized experiment later found it didn''t. Confounding by healthier lifestyles explained the original association."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a08fb9fef9c79f', 'les_a32f2e9c0e9fc9', 1, 'practice', 'multiple_choice', 1, 'Researchers randomly assign 60 volunteers to drink coffee or decaf and measure reaction time. This is…', '{"choices":["An observational study","An experiment","A sample survey","A census"],"answer":1}', '[]', 'Treatments are imposed.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8051e56a1f702b', 'les_a32f2e9c0e9fc9', 2, 'practice', 'multiple_choice', 2, 'In that study, the response variable is…', '{"choices":["Coffee type","Reaction time","The volunteers","Random assignment"],"answer":1}', '[]', 'Reaction time is measured as the outcome.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_68e1f097674f77', 'les_a32f2e9c0e9fc9', 3, 'practice', 'multiple_choice', 2, 'Students who eat breakfast have higher grades. Which is a plausible confounding variable?', '{"choices":["Grade point average","Family routines and support","Breakfast","Test difficulty"],"answer":1}', '[]', 'Home routines could affect both breakfast and grades.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f7eb6e14a2b784', 'les_a32f2e9c0e9fc9', 4, 'review', 'multiple_choice', 3, 'Why can''t an observational study prove causation?', '{"choices":["Its samples are always small","Other variables linked to the explanatory variable might cause the response","It has no response variable","It uses random assignment"],"answer":1}', '[]', 'Without random assignment, confounding can''t be ruled out.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_8954756507bcfa', 'subj_math', 'study-design', 'Study design', 'How data are produced (sample surveys, observational studies, experiments) and what conclusions each design supports.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a32f2e9c0e9fc9', (SELECT id FROM concepts WHERE slug = 'study-design'));

-- Lesson: periodic-phenomena
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_1101db5457199f', 'periodic-phenomena', 'Periodic phenomena', 'Describe repeating patterns with period, amplitude and midline, and read these features from graphs, tables and situations such as Ferris wheels and tides.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e414ddd0bb2e11', 'les_1101db5457199f', 1, 'Define a periodic function and identify its period.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_cd70bed5126255', 'les_1101db5457199f', 2, 'Find the amplitude and midline from maximum and minimum values.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0dd76242c458eb', 'les_1101db5457199f', 3, 'Use one period of behavior to predict values far in the future.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e414ddd0bb2e11', 'les_1101db5457199f', 'learn', 1, 'definition', '{"term":"Periodic function","body":"A function $f$ is periodic if there is a positive number $p$ with $f(x + p) = f(x)$ for all $x$. The smallest such $p$ is the period. Knowing one period of the graph tells you the whole graph."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cd70bed5126255', 'les_1101db5457199f', 'learn', 2, 'definition', '{"term":"Amplitude and midline","body":"For a periodic function that oscillates between a maximum $M$ and a minimum $m$: the midline is $y = \\frac{M + m}{2}$ and the amplitude is $\\frac{M - m}{2}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0dd76242c458eb', 'les_1101db5457199f', 'learn', 3, 'worked_example', '{"title":"A Ferris wheel 40 m across has its center 25 m above the ground and turns once every 8 minutes.","steps":[{"latex":"M = 45,\\ m = 5","explanation":"Top and bottom of the wheel."},{"latex":"\\text{midline } y = 25,\\ \\text{amplitude } 20","explanation":""},{"latex":"\\text{period } 8 \\text{ min}","explanation":"A rider''s height repeats every 8 minutes."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c60786aa4e76ac', 'les_1101db5457199f', 'learn', 4, 'worked_example', '{"title":"A rider is at the bottom at $t = 0$. Where are they at $t = 26$ minutes?","steps":[{"latex":"26 = 3 \\cdot 8 + 2","explanation":"Three full turns plus 2 minutes."},{"latex":"2 \\text{ min} = \\tfrac{1}{4} \\text{ turn}","explanation":"Halfway up: at the midline, 25 m."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9fdbd400b6c2a8', 'les_1101db5457199f', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Tides, daylight hours, heartbeats, sound waves and alternating current are all periodic. Engineers and scientists describe them by period (or frequency) and amplitude."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e414ddd0bb2e11', 'les_1101db5457199f', 1, 'practice', 'numeric', 1, 'A periodic function has maximum 18 and minimum 4. What is its amplitude?', '{"answer":7}', '[]', '$\frac{18 - 4}{2} = 7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cd70bed5126255', 'les_1101db5457199f', 2, 'practice', 'numeric', 1, 'For the same function, the midline is $y = ?$', '{"answer":11}', '[]', '$\frac{18 + 4}{2} = 11$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0dd76242c458eb', 'les_1101db5457199f', 3, 'practice', 'numeric', 2, '$f$ has period 6 and $f(2) = 5$. Find $f(20)$.', '{"answer":5}', '["20 − 2 is a multiple of 6."]', '$20 = 2 + 3 \cdot 6$, so $f(20) = f(2) = 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c60786aa4e76ac', 'les_1101db5457199f', 4, 'practice', 'multiple_choice', 2, 'A tide is high at 4:00 a.m. and the next high is at 4:24 p.m. What is the period?', '{"choices":["12 h 24 min","6 h 12 min","24 h","12 h"],"answer":0}', '[]', 'From high to the next high is one full period.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9fdbd400b6c2a8', 'les_1101db5457199f', 5, 'review', 'numeric', 3, 'On the Ferris wheel above (starting at the bottom at $t = 0$), what is the rider''s height in meters at $t = 12$ minutes?', '{"answer":45,"unit":"m"}', '[]', '12 = 8 + 4: half a turn past the bottom, so at the top, 45 m.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_1101db5457199f', (SELECT id FROM concepts WHERE slug = 'trig-functions'));

-- Lesson: polar-rates-of-change
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0c3f4ff31c3dff', 'polar-rates-of-change', 'Rates of change in polar functions', 'Interpret how r changes as θ changes in a polar function: whether points move toward or away from the pole, and average rates of change of r over intervals of θ.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f3c3f8057b6110', 'les_0c3f4ff31c3dff', 1, 'Compute the average rate of change of r = f(θ) over an interval of θ.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f1fa1dfd0c1919', 'les_0c3f4ff31c3dff', 2, 'Decide whether points on a polar graph are moving toward or away from the pole.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a804a6e738ec9e', 'les_0c3f4ff31c3dff', 3, 'Connect sign and change of r to the shape of the polar graph.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f3c3f8057b6110', 'les_0c3f4ff31c3dff', 'learn', 1, 'definition', '{"term":"Average rate of change of r","body":"For $r = f(\\theta)$ on $[\\alpha, \\beta]$, the average rate of change is $\\frac{f(\\beta) - f(\\alpha)}{\\beta - \\alpha}$: the average change in radius per radian."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f1fa1dfd0c1919', 'les_0c3f4ff31c3dff', 'learn', 2, 'definition', '{"term":"Toward or away from the pole","body":"Distance from the pole is $|r|$. If $r > 0$ and increasing, or $r < 0$ and decreasing, points move away from the pole. If $r > 0$ and decreasing, or $r < 0$ and increasing, they move toward it."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a804a6e738ec9e', 'les_0c3f4ff31c3dff', 'learn', 3, 'worked_example', '{"title":"$r = 3\\sin(2\\theta)$ on $\\left[0, \\frac{\\pi}{4}\\right]$ and $\\left[\\frac{\\pi}{4}, \\frac{\\pi}{2}\\right]$","steps":[{"latex":"r: 0 \\to 3","explanation":"Positive and increasing: moving away from the pole."},{"latex":"\\frac{3 - 0}{\\pi/4} = \\frac{12}{\\pi} \\approx 3.82","explanation":"Average rate on the first interval."},{"latex":"r: 3 \\to 0","explanation":"Positive and decreasing: back toward the pole, finishing one petal."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2a46fbd9419480', 'les_0c3f4ff31c3dff', 'experiment', 4, 'activity', '{"activity":"polar-graph","title":"Watch r grow and shrink","params":{"kind":"rose","a":2,"b":3,"n":2}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1863a21c7f51f8', 'les_0c3f4ff31c3dff', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Move $\\theta$ slowly and watch the readout of $r$. Where $r$ passes through 0, the curve returns to the pole."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c30457dbe0127d', 'les_0c3f4ff31c3dff', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Radar and antenna patterns are polar graphs; how fast the radius changes with angle tells engineers how sharply a signal falls off as you turn away from the main direction."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f3c3f8057b6110', 'les_0c3f4ff31c3dff', 1, 'practice', 'numeric', 2, 'For $r = 4\cos\theta$, find the average rate of change of $r$ on $\left[0, \frac{\pi}{3}\right]$, to three decimal places.', '{"answer":-1.91,"tolerance":0.002}', '["$r(0) = 4$, $r(\\pi/3) = 2$."]', '$\frac{2 - 4}{\pi/3} = -\frac{6}{\pi} \approx -1.910$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f1fa1dfd0c1919', 'les_0c3f4ff31c3dff', 2, 'practice', 'multiple_choice', 2, 'On an interval where $r < 0$ and $r$ is decreasing, points on the graph are…', '{"choices":["moving toward the pole","moving away from the pole","fixed","on the polar axis"],"answer":1}', '[]', '$|r|$ is increasing.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a804a6e738ec9e', 'les_0c3f4ff31c3dff', 3, 'practice', 'multiple_choice', 2, 'For $r = 2 + \cos\theta$ on $[0, \pi]$, points move…', '{"choices":["away from the pole","toward the pole","away, then toward","toward, then away"],"answer":1}', '[]', '$r$ falls from 3 to 1 and stays positive.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2a46fbd9419480', 'les_0c3f4ff31c3dff', 4, 'review', 'numeric', 3, 'For $r = \theta$ (a spiral), what is the average rate of change of $r$ on $[\pi, 3\pi]$?', '{"answer":1}', '[]', '$\frac{3\pi - \pi}{2\pi} = 1$: the radius grows 1 unit per radian.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0c3f4ff31c3dff', (SELECT id FROM concepts WHERE slug = 'polar-coordinates'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0c3f4ff31c3dff', (SELECT id FROM concepts WHERE slug = 'rate-of-change'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_0c3f4ff31c3dff', (SELECT id FROM formulas WHERE slug = 'polar-conversion'), 1);

-- Lesson: probability-rules
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_6193ebe8c598f1', 'probability-rules', 'Addition and multiplication rules', 'Use the general addition rule for ''or'' events, the multiplication rule for ''and'' events (independent or not), and Venn diagrams and tree diagrams to organize them.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d3d75319b2b01b', 'les_6193ebe8c598f1', 1, 'Use P(A or B) = P(A) + P(B) − P(A and B), and the special case for mutually exclusive events.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1d4efb55b6ae72', 'les_6193ebe8c598f1', 2, 'Use P(A and B) = P(A)·P(B | A), and P(A)·P(B) for independent events.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f24d3249935a92', 'les_6193ebe8c598f1', 3, 'Organize probabilities with Venn and tree diagrams.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d3d75319b2b01b', 'les_6193ebe8c598f1', 'learn', 1, 'definition', '{"term":"General addition rule","body":"$P(A \\text{ or } B) = P(A) + P(B) - P(A \\text{ and } B)$. Subtracting removes the overlap counted twice. If $A$ and $B$ are mutually exclusive (can''t both happen), $P(A \\text{ or } B) = P(A) + P(B)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1d4efb55b6ae72', 'les_6193ebe8c598f1', 'learn', 2, 'worked_example', '{"title":"Draw one card from a standard deck. Find $P(\\text{heart or face card})$.","steps":[{"latex":"\\frac{13}{52} + \\frac{12}{52} - \\frac{3}{52}","explanation":"Three face cards are hearts."},{"latex":"= \\frac{22}{52} = \\frac{11}{26} \\approx 0.423","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f24d3249935a92', 'les_6193ebe8c598f1', 'learn', 3, 'definition', '{"term":"General multiplication rule","body":"$P(A \\text{ and } B) = P(A) \\cdot P(B \\mid A)$. If $A$ and $B$ are independent, $P(B \\mid A) = P(B)$, so $P(A \\text{ and } B) = P(A)P(B)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_345df84bd7633c', 'les_6193ebe8c598f1', 'learn', 4, 'worked_example', '{"title":"Draw two cards without replacement. Find $P(\\text{both aces})$.","steps":[{"latex":"\\frac{4}{52} \\cdot \\frac{3}{51} = \\frac{12}{2652}","explanation":"The second draw depends on the first."},{"latex":"\\approx 0.0045","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5ad726f1611ca7', 'les_6193ebe8c598f1', 'learn', 5, 'callout', '{"tone":"warning","title":"Mutually exclusive ≠ independent","body":"If $A$ and $B$ are mutually exclusive with positive probabilities, knowing $A$ happened tells you $B$ didn''t, so they are dependent."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0bb2d79aed4340', 'les_6193ebe8c598f1', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Reliability engineers compute the chance a system fails using these rules: parallel backups fail only if all fail (''and''), while a chain fails if any link fails (''or'')."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d3d75319b2b01b', 'les_6193ebe8c598f1', 1, 'practice', 'numeric', 1, '$P(A) = 0.5$, $P(B) = 0.4$ and $P(A \text{ and } B) = 0.2$. Find $P(A \text{ or } B)$.', '{"answer":0.7,"tolerance":0.001}', '[]', '$0.5 + 0.4 - 0.2 = 0.7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1d4efb55b6ae72', 'les_6193ebe8c598f1', 2, 'practice', 'numeric', 1, 'Roll two fair dice. Find $P(\text{both show 6})$ to four decimal places.', '{"answer":0.0278,"tolerance":0.0001}', '[]', '$\frac{1}{6} \cdot \frac{1}{6} = \frac{1}{36} \approx 0.0278$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f24d3249935a92', 'les_6193ebe8c598f1', 3, 'practice', 'numeric', 2, 'A backup generator fails 5% of the time and a second, independent one fails 10% of the time. What is the probability that both fail?', '{"answer":0.005,"tolerance":0.0001}', '[]', '$0.05 \cdot 0.10 = 0.005$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_345df84bd7633c', 'les_6193ebe8c598f1', 4, 'practice', 'multiple_choice', 2, 'Events $A$ and $B$ are mutually exclusive, with $P(A) = 0.3$ and $P(B) = 0.2$. Are they independent?', '{"choices":["Yes","No","Only if P(A or B) = 0.5","Can''t tell"],"answer":1}', '[]', '$P(A \text{ and } B) = 0 \ne 0.3 \cdot 0.2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5ad726f1611ca7', 'les_6193ebe8c598f1', 5, 'review', 'numeric', 3, 'A test detects a condition 90% of the time when present; 2% of people have it. Find $P(\text{has it and tests positive})$.', '{"answer":0.018,"tolerance":0.0001}', '[]', '$0.02 \cdot 0.90 = 0.018$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_6193ebe8c598f1', (SELECT id FROM concepts WHERE slug = 'probability'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_6193ebe8c598f1', (SELECT id FROM formulas WHERE slug = 'probability-rules'), 1);

-- Lesson: rational-end-behavior
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ec461eb0d776ee', 'rational-end-behavior', 'Rational functions and end behavior', 'Predict what a rational function does as x grows without bound by comparing the degrees and leading terms of its numerator and denominator.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2ae7630e1511e6', 'les_ec461eb0d776ee', 1, 'Determine a rational function''s end behavior from the ratio of leading terms.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_57334c04b032e3', 'les_ec461eb0d776ee', 2, 'Find horizontal asymptotes by comparing degrees.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0d807fffa0e236', 'les_ec461eb0d776ee', 3, 'Find a slant asymptote by polynomial division when the numerator''s degree is one more.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2ae7630e1511e6', 'les_ec461eb0d776ee', 'learn', 1, 'definition', '{"term":"End behavior from leading terms","body":"For large $|x|$, a polynomial behaves like its leading term. So $r(x) = \\frac{p(x)}{q(x)}$ behaves like the ratio of the leading terms of $p$ and $q$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_57334c04b032e3', 'les_ec461eb0d776ee', 'learn', 2, 'definition', '{"term":"Three cases","body":"If $\\deg p < \\deg q$, $r(x) \\to 0$: horizontal asymptote $y = 0$. If the degrees are equal, $r(x) \\to \\frac{a}{b}$, the ratio of leading coefficients. If $\\deg p > \\deg q$, $r(x)$ grows without bound; when $\\deg p = \\deg q + 1$, the quotient from division is a slant asymptote."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0d807fffa0e236', 'les_ec461eb0d776ee', 'learn', 3, 'worked_example', '{"title":"$r(x) = \\dfrac{3x^2 + 1}{x^2 - 4}$","steps":[{"latex":"\\frac{3x^2}{x^2} = 3","explanation":"Equal degrees: ratio of leading coefficients."},{"latex":"\\lim_{x \\to \\pm\\infty} r(x) = 3","explanation":"Horizontal asymptote y = 3."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_584fe48b3a2697', 'les_ec461eb0d776ee', 'learn', 4, 'worked_example', '{"title":"$r(x) = \\dfrac{2x + 1}{x^2 + 1}$","steps":[{"latex":"\\frac{2x}{x^2} = \\frac{2}{x} \\to 0","explanation":"Lower degree on top: y = 0."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_714c4395d05ebd', 'les_ec461eb0d776ee', 'learn', 5, 'worked_example', '{"title":"$r(x) = \\dfrac{x^2 + 1}{x - 1}$","steps":[{"latex":"x^2 + 1 = (x - 1)(x + 1) + 2","explanation":"Divide."},{"latex":"r(x) = x + 1 + \\frac{2}{x - 1}","explanation":"The remainder term goes to 0."},{"latex":"y = x + 1","explanation":"Slant asymptote."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dc54fb5fc5fefc', 'les_ec461eb0d776ee', 'experiment', 6, 'activity', '{"activity":"rational-graph","title":"Watch the graph flatten toward its asymptote","params":{"a":2,"h":1,"k":-1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fcf7855dbcd604', 'les_ec461eb0d776ee', 'experiment', 7, 'callout', '{"tone":"tip","title":"Try this","body":"Here $y = \\frac{2}{x - 1} - 1$. Drag far left and right on the graph in your mind: the outputs approach $k = -1$. Change $k$ and the horizontal asymptote moves with it."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_306d5849a668a6', 'les_ec461eb0d776ee', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"The average cost per item, $\\frac{5000 + 3x}{x}$, approaches 3 dollars as production $x$ grows: the fixed cost spreads out, and the end behavior is the long-run cost per item."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2ae7630e1511e6', 'les_ec461eb0d776ee', 1, 'practice', 'numeric', 1, 'Find the horizontal asymptote $y = ?$ of $\dfrac{5x^3 - x}{2x^3 + 7}$.', '{"answer":2.5,"tolerance":0.001}', '["Equal degrees."]', '$\frac{5}{2} = 2.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_57334c04b032e3', 'les_ec461eb0d776ee', 2, 'practice', 'numeric', 1, 'What does $\dfrac{4x}{x^2 + 1}$ approach as $x \to \infty$?', '{"answer":0,"tolerance":0.001}', '[]', 'Degree 1 over degree 2: it approaches 0.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0d807fffa0e236', 'les_ec461eb0d776ee', 3, 'practice', 'multiple_choice', 2, 'Which function has a slant asymptote?', '{"choices":["$\\frac{x^2}{x^2 + 1}$","$\\frac{x^3 + 2}{x - 1}$","$\\frac{x^2 - 3}{x + 2}$","$\\frac{x}{x^2 - 9}$"],"answer":2}', '["The numerator''s degree must be exactly one more."]', '$\frac{x^2 - 3}{x + 2}$ has degrees 2 and 1. (The cubic over linear grows like $x^2$, a parabola-like end behavior, not a line.)');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_584fe48b3a2697', 'les_ec461eb0d776ee', 4, 'practice', 'numeric', 2, 'The average cost of making $x$ items is $C(x) = \dfrac{1200 + 8x}{x}$ dollars. What value does the average cost approach for very large $x$?', '{"answer":8,"tolerance":0.001,"unit":"dollars"}', '[]', '$\frac{8x}{x} = 8$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_714c4395d05ebd', 'les_ec461eb0d776ee', 5, 'review', 'multiple_choice', 3, 'As $x \to -\infty$, $\dfrac{-2x^2 + x}{x - 5}$…', '{"choices":["approaches −2","approaches 0","increases without bound","decreases without bound"],"answer":2}', '["Leading-term ratio $\\frac{-2x^2}{x} = -2x$."]', 'For large negative $x$, $-2x$ is large and positive, so the function increases without bound.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ec461eb0d776ee', (SELECT id FROM concepts WHERE slug = 'rational-functions'));

-- Lesson: rational-zeros-sign
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_298db8f659066e', 'rational-zeros-sign', 'Rational functions and zeros', 'Find the zeros of rational functions, tell them apart from holes, and use sign charts to solve rational inequalities.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_44fda3456bbd76', 'les_298db8f659066e', 1, 'Find the real zeros of a rational function from its numerator.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e8ccb2aa1c2ad5', 'les_298db8f659066e', 2, 'Exclude inputs that are also zeros of the denominator (holes or asymptotes).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_46fe24e18d2ce0', 'les_298db8f659066e', 3, 'Build a sign chart to solve rational inequalities.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_44fda3456bbd76', 'les_298db8f659066e', 'learn', 1, 'definition', '{"term":"Zeros of a rational function","body":"The real zeros of $r(x) = \\frac{p(x)}{q(x)}$ are the real zeros of $p$ that are in the domain of $r$. An input that makes both $p$ and $q$ zero is not a zero of $r$: after cancelling, it''s usually a hole."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e8ccb2aa1c2ad5', 'les_298db8f659066e', 'learn', 2, 'worked_example', '{"title":"Zeros of $r(x) = \\dfrac{(x - 2)(x + 1)}{(x - 3)(x + 1)}$","steps":[{"latex":"p(x) = 0 \\text{ at } x = 2, -1","explanation":""},{"latex":"x = -1 \\text{ also zeros } q","explanation":"Not in the domain: a hole."},{"latex":"\\text{Zero: } x = 2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_46fe24e18d2ce0', 'les_298db8f659066e', 'learn', 3, 'definition', '{"term":"Sign charts","body":"A rational function can change sign only at a real zero of the numerator or denominator. Mark those points on a number line, then test one value in each interval."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_36258113b09d2b', 'les_298db8f659066e', 'learn', 4, 'worked_example', '{"title":"Solve $\\dfrac{x - 1}{x + 2} \\ge 0$","steps":[{"latex":"\\text{Critical points: } x = 1,\\ x = -2","explanation":""},{"latex":"x = -3: \\tfrac{-4}{-1} > 0;\\ x = 0: \\tfrac{-1}{2} < 0;\\ x = 2: \\tfrac{1}{4} > 0","explanation":"Test each interval."},{"latex":"x < -2 \\text{ or } x \\ge 1","explanation":"Include x = 1 (the function equals 0) but never x = −2."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fbd79629a066e8', 'les_298db8f659066e', 'learn', 5, 'callout', '{"tone":"warning","title":"Never include the denominator''s zeros","body":"Even with $\\ge$ or $\\le$, an input that makes the denominator 0 is never part of the solution."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_04d7552831daa9', 'les_298db8f659066e', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Lens and circuit formulas are rational. Asking \"when is the output positive?\" (a real image, a positive current) is a rational inequality."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_44fda3456bbd76', 'les_298db8f659066e', 1, 'practice', 'numeric', 1, 'Find the zero of $\dfrac{x^2 - 9}{x + 3}$.', '{"answer":3}', '["Factor the numerator."]', '$\frac{(x - 3)(x + 3)}{x + 3}$: $x = -3$ is a hole, so the only zero is $x = 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e8ccb2aa1c2ad5', 'les_298db8f659066e', 2, 'practice', 'multiple_choice', 2, 'How many real zeros does $\dfrac{x^2 + 4}{x - 1}$ have?', '{"choices":["0","1","2","Infinitely many"],"answer":0}', '[]', '$x^2 + 4 > 0$ for every real $x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_46fe24e18d2ce0', 'les_298db8f659066e', 3, 'practice', 'multiple_choice', 2, 'Solve $\dfrac{x + 4}{x - 3} < 0$.', '{"choices":["$-4 < x < 3$","$x < -4$ or $x > 3$","$-4 \\le x < 3$","$x > 3$"],"answer":0}', '["Test a value between −4 and 3, such as 0."]', 'At $x = 0$: $\frac{4}{-3} < 0$. Outside the interval the sign is positive.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_36258113b09d2b', 'les_298db8f659066e', 4, 'review', 'multiple_choice', 3, 'Which set solves $\dfrac{x}{(x - 2)^2} \ge 0$?', '{"choices":["$x \\ge 0$","$x \\ge 0,\\ x \\ne 2$","$0 \\le x < 2$","$x > 2$"],"answer":1}', '["A squared factor doesn''t change sign."]', 'The denominator is positive except at $x = 2$, where it''s undefined. So the sign is the sign of $x$: $x \ge 0$ with $x \ne 2$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_298db8f659066e', (SELECT id FROM concepts WHERE slug = 'rational-functions'));

-- Lesson: residuals
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_77181084591dfd', 'residuals', 'Residuals', 'Compute and interpret residuals, read residual plots to judge whether a linear model is appropriate, and interpret r² and the standard deviation of the residuals.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_edaedfe9f1bfb9', 'les_77181084591dfd', 1, 'Compute residuals as actual minus predicted, and interpret their sign.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3eddc2f0e2dcc8', 'les_77181084591dfd', 2, 'Use a residual plot to judge whether a linear model fits.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9c0e19a454a7a6', 'les_77181084591dfd', 3, 'Interpret r² as the fraction of variation in y explained by the line.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_edaedfe9f1bfb9', 'les_77181084591dfd', 'learn', 1, 'definition', '{"term":"Residual","body":"$\\text{residual} = y - \\hat{y}$. Positive: the point is above the line (the model underpredicted). Negative: below the line. Least-squares residuals always sum to 0."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3eddc2f0e2dcc8', 'les_77181084591dfd', 'learn', 2, 'worked_example', '{"title":"For $\\hat{y} = 2.2 + 0.6x$ with data $(1, 2), (2, 4), (3, 5), (4, 4), (5, 5)$","steps":[{"latex":"\\hat{y}: 2.8, 3.4, 4.0, 4.6, 5.2","explanation":""},{"latex":"\\text{residuals: } -0.8, 0.6, 1.0, -0.6, -0.2","explanation":""},{"latex":"\\text{sum} = 0","explanation":"As always for least squares."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9c0e19a454a7a6', 'les_77181084591dfd', 'learn', 3, 'definition', '{"term":"Residual plots","body":"Plot residuals against $x$. A random scatter around 0 means a line fits. A curved pattern means a curve fits better. A fan shape means predictions are less reliable for some $x$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8990924074997d', 'les_77181084591dfd', 'learn', 4, 'definition', '{"term":"r² and s","body":"$r^2$ is the fraction of the variation in $y$ that is accounted for by the linear model. The standard deviation of the residuals, $s$, is the typical size of a prediction error."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0c59f824112293', 'les_77181084591dfd', 'learn', 5, 'worked_example', '{"title":"Interpret $r^2 = 0.6$ for the data above","steps":[{"latex":"r = 0.775,\\ r^2 \\approx 0.60","explanation":""},{"latex":"\\text{about 60\\% of the variation in } y \\text{ is explained by the linear relationship with } x","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d8681e68bd904b', 'les_77181084591dfd', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Appraisers look at large positive residuals to spot homes priced high for their size; scientists check residual plots before trusting a model."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_edaedfe9f1bfb9', 'les_77181084591dfd', 1, 'practice', 'numeric', 1, 'A model predicts 140 and the actual value is 132. What is the residual?', '{"answer":-8}', '[]', '$132 - 140 = -8$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3eddc2f0e2dcc8', 'les_77181084591dfd', 2, 'practice', 'numeric', 2, 'Using $\hat{y} = 2.2 + 0.6x$, find the residual for the point $(3, 5)$.', '{"answer":1,"tolerance":0.001}', '[]', '$5 - 4.0 = 1.0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9c0e19a454a7a6', 'les_77181084591dfd', 3, 'practice', 'multiple_choice', 2, 'A residual plot shows a clear U-shaped curve. What does that mean?', '{"choices":["The line is a good fit","A nonlinear model would fit better","r is close to 1","There are no outliers"],"answer":1}', '[]', 'Curved residuals mean the relationship is curved.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8990924074997d', 'les_77181084591dfd', 4, 'review', 'numeric', 3, 'If $r = -0.9$, what percent of the variation in $y$ is explained by the linear model?', '{"answer":81,"tolerance":0.1,"unit":"%"}', '[]', '$r^2 = 0.81$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_ea585073ff8843', 'subj_math', 'regression', 'Linear regression', 'Fitting the least-squares line ŷ = a + bx to predict a response variable from an explanatory variable.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_77181084591dfd', (SELECT id FROM concepts WHERE slug = 'regression'));

-- Lesson: sampling-distributions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_3e74369b9847ad', 'sampling-distributions', 'Sampling distributions', 'Understand that statistics vary from sample to sample, and describe the sampling distributions of a sample proportion and a sample mean, including the Central Limit Theorem.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5a77fc93f2f49a', 'les_3e74369b9847ad', 1, 'Distinguish a parameter from a statistic.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2bb75717855129', 'les_3e74369b9847ad', 2, 'Describe the center, spread and shape of the sampling distribution of p̂ and of x̄.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bb448c95fdbd7b', 'les_3e74369b9847ad', 3, 'Explain how sample size affects variability, and state the Central Limit Theorem.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5a77fc93f2f49a', 'les_3e74369b9847ad', 'learn', 1, 'definition', '{"term":"Parameter and statistic","body":"A parameter describes a population (such as $p$ or $\\mu$) and is usually unknown. A statistic describes a sample (such as $\\hat{p}$ or $\\bar{x}$) and varies from sample to sample."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2bb75717855129', 'les_3e74369b9847ad', 'learn', 2, 'definition', '{"term":"Sampling distribution","body":"The distribution of a statistic''s values over all possible random samples of the same size."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bb448c95fdbd7b', 'les_3e74369b9847ad', 'learn', 3, 'definition', '{"term":"Sample proportion","body":"Mean $p$ (unbiased), standard deviation $\\sqrt{\\frac{p(1 - p)}{n}}$ (when the sample is under 10% of the population), approximately normal when $np \\ge 10$ and $n(1 - p) \\ge 10$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_23461ee1d02f04', 'les_3e74369b9847ad', 'learn', 4, 'definition', '{"term":"Sample mean","body":"Mean $\\mu$, standard deviation $\\frac{\\sigma}{\\sqrt{n}}$. Central Limit Theorem: for large $n$ (often $n \\ge 30$), $\\bar{x}$ is approximately normal whatever the population''s shape."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fd6e995005f327', 'les_3e74369b9847ad', 'learn', 5, 'worked_example', '{"title":"60% of a city''s voters support a measure. Describe $\\hat{p}$ for random samples of 100.","steps":[{"latex":"\\text{center: } 0.6","explanation":""},{"latex":"\\text{SD: } \\sqrt{\\tfrac{0.6 \\cdot 0.4}{100}} \\approx 0.049","explanation":""},{"latex":"np = 60,\\ n(1 - p) = 40 \\Rightarrow \\text{approximately normal}","explanation":"About 95% of samples give p̂ between 0.50 and 0.70."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_841df6da4f0205', 'les_3e74369b9847ad', 'experiment', 6, 'activity', '{"activity":"dice-simulation","title":"Statistics settle down as n grows"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6d08834a6bcc49', 'les_3e74369b9847ad', 'experiment', 7, 'callout', '{"tone":"tip","title":"Size matters, as a square root","body":"To halve the standard deviation of a statistic, you need four times the sample size."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_50a9d0a43200a8', 'les_3e74369b9847ad', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Every poll''s margin of error comes from the sampling distribution of $\\hat{p}$; quality engineers chart sample means because the CLT makes them nearly normal."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5a77fc93f2f49a', 'les_3e74369b9847ad', 1, 'practice', 'multiple_choice', 1, 'The average height of all U.S. adults is a…', '{"choices":["statistic","parameter","sample","sampling distribution"],"answer":1}', '[]', 'It describes the whole population.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2bb75717855129', 'les_3e74369b9847ad', 2, 'practice', 'numeric', 2, 'A population has $\sigma = 12$. Find the standard deviation of $\bar{x}$ for samples of size 36.', '{"answer":2}', '[]', '$\frac{12}{\sqrt{36}} = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bb448c95fdbd7b', 'les_3e74369b9847ad', 3, 'practice', 'multiple_choice', 2, 'Sample size goes from 100 to 400. The standard deviation of $\hat{p}$…', '{"choices":["doubles","halves","is divided by 4","doesn''t change"],"answer":1}', '[]', 'Multiplying $n$ by 4 divides the SD by $\sqrt{4} = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_23461ee1d02f04', 'les_3e74369b9847ad', 4, 'review', 'multiple_choice', 3, 'A population is strongly skewed right. For samples of size 50, the distribution of $\bar{x}$ is…', '{"choices":["strongly skewed right","approximately normal","uniform","skewed left"],"answer":1}', '[]', 'By the Central Limit Theorem.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_3e74369b9847ad', 'subj_math', 'sampling-distributions', 'Sampling distributions', 'The distribution of a statistic''s values over all possible samples of the same size.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_3e74369b9847ad', (SELECT id FROM concepts WHERE slug = 'sampling-distributions'));

-- Lesson: sampling-methods
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7dbe1ef60a868c', 'sampling-methods', 'Sampling methods', 'Choose random samples with simple random, stratified, cluster and systematic sampling, and recognize convenience and voluntary response samples as biased.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7f9f70ce67368c', 'les_7dbe1ef60a868c', 1, 'Select a simple random sample using a random number generator or table.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f39854298a9db5', 'les_7dbe1ef60a868c', 2, 'Describe stratified, cluster and systematic random samples and when each is useful.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_142dc170a9f4b1', 'les_7dbe1ef60a868c', 3, 'Explain why convenience and voluntary response samples are biased.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7f9f70ce67368c', 'les_7dbe1ef60a868c', 'learn', 1, 'definition', '{"term":"Simple random sample (SRS)","body":"Every group of $n$ individuals has the same chance of being chosen. Label individuals 1 to $N$ and use a random number generator to pick $n$ different labels."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f39854298a9db5', 'les_7dbe1ef60a868c', 'learn', 2, 'definition', '{"term":"Stratified random sample","body":"Split the population into groups of similar individuals (strata), such as grade levels, and take an SRS from each. Useful when the strata differ on the variable of interest; it gives more precise estimates."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_142dc170a9f4b1', 'les_7dbe1ef60a868c', 'learn', 3, 'definition', '{"term":"Cluster sample","body":"Split the population into groups that each look like the population (clusters), such as homerooms, randomly choose some clusters, and include everyone in them. Useful because it''s cheaper and easier."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e08002545ceeb0', 'les_7dbe1ef60a868c', 'learn', 4, 'definition', '{"term":"Systematic random sample","body":"Choose a random starting point among the first $k$ individuals, then take every $k$th individual on the list."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1c126b5d1dd9be', 'les_7dbe1ef60a868c', 'learn', 5, 'worked_example', '{"title":"A school of 1,200 students (300 per grade) wants opinions on a new schedule.","steps":[{"latex":"\\text{stratified: an SRS of 25 from each grade}","explanation":"Grades may differ in opinion."},{"latex":"\\text{cluster: randomly pick 4 of the 48 homerooms and survey everyone in them}","explanation":"Fast and cheap."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8bf74f71e51d93', 'les_7dbe1ef60a868c', 'learn', 6, 'callout', '{"tone":"warning","title":"Bad samples","body":"A convenience sample (whoever is easy to reach) and a voluntary response sample (whoever chooses to respond) are biased: they systematically over-represent some groups. Bigger samples of this kind don''t fix the bias."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_70189c576123ec', 'les_7dbe1ef60a868c', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"National polls use stratified, multistage samples; manufacturers use systematic samples from production lines to check quality."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7f9f70ce67368c', 'les_7dbe1ef60a868c', 1, 'practice', 'multiple_choice', 1, 'A radio host asks listeners to call in with their opinions. This is a…', '{"choices":["Simple random sample","Voluntary response sample","Stratified sample","Cluster sample"],"answer":1}', '[]', 'People choose to respond, typically those with strong opinions.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f39854298a9db5', 'les_7dbe1ef60a868c', 2, 'practice', 'multiple_choice', 2, 'A researcher randomly selects 10 city blocks and surveys every household on them. This is a…', '{"choices":["Stratified sample","Cluster sample","Systematic sample","Convenience sample"],"answer":1}', '[]', 'Whole groups (blocks) are chosen at random.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_142dc170a9f4b1', 'les_7dbe1ef60a868c', 3, 'practice', 'multiple_choice', 2, 'Why might a company stratify a customer survey by region?', '{"choices":["It''s always cheaper","Regions may differ in satisfaction, and stratifying ensures each is represented","It removes all bias","It makes the sample voluntary"],"answer":1}', '[]', 'Stratifying on a variable related to the response improves precision.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e08002545ceeb0', 'les_7dbe1ef60a868c', 4, 'review', 'multiple_choice', 3, 'An online poll gets 50,000 responses. Which is true?', '{"choices":["The large size guarantees accuracy","It may still be badly biased because respondents chose themselves","It''s a simple random sample","It''s a census"],"answer":1}', '[]', 'Size doesn''t fix voluntary response bias.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7dbe1ef60a868c', (SELECT id FROM concepts WHERE slug = 'sampling'));

-- Lesson: secant-cosecant-cotangent
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d1ace174ece365', 'secant-cosecant-cotangent', 'The secant, cosecant and cotangent functions', 'Define secant, cosecant and cotangent as reciprocals of cosine, sine and tangent, evaluate them, and locate their asymptotes, domains and ranges.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_15a189d995305d', 'les_d1ace174ece365', 1, 'Evaluate sec θ, csc θ and cot θ from sine, cosine and tangent values.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fd18331a82a10a', 'les_d1ace174ece365', 2, 'Find where each reciprocal function is undefined and has vertical asymptotes.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2ef424212d8c74', 'les_d1ace174ece365', 3, 'Describe the ranges of secant and cosecant.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_15a189d995305d', 'les_d1ace174ece365', 'learn', 1, 'definition', '{"term":"Reciprocal functions","body":"$\\sec\\theta = \\frac{1}{\\cos\\theta}$, $\\csc\\theta = \\frac{1}{\\sin\\theta}$, $\\cot\\theta = \\frac{1}{\\tan\\theta} = \\frac{\\cos\\theta}{\\sin\\theta}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fd18331a82a10a', 'les_d1ace174ece365', 'learn', 2, 'definition', '{"term":"Where they''re undefined","body":"Secant has vertical asymptotes where $\\cos\\theta = 0$ ($\\theta = \\frac{\\pi}{2} + k\\pi$). Cosecant and cotangent have them where $\\sin\\theta = 0$ ($\\theta = k\\pi$)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2ef424212d8c74', 'les_d1ace174ece365', 'learn', 3, 'definition', '{"term":"Ranges","body":"Because $|\\cos\\theta| \\le 1$, $|\\sec\\theta| \\ge 1$; the same holds for cosecant. Cotangent takes every real value."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_92cdb4dda9022c', 'les_d1ace174ece365', 'learn', 4, 'worked_example', '{"title":"Evaluate at $\\theta = \\frac{\\pi}{3}$","steps":[{"latex":"\\cos\\tfrac{\\pi}{3} = \\tfrac{1}{2} \\Rightarrow \\sec\\tfrac{\\pi}{3} = 2","explanation":""},{"latex":"\\sin\\tfrac{\\pi}{3} = \\tfrac{\\sqrt{3}}{2} \\Rightarrow \\csc\\tfrac{\\pi}{3} = \\tfrac{2}{\\sqrt{3}} \\approx 1.155","explanation":""},{"latex":"\\tan\\tfrac{\\pi}{3} = \\sqrt{3} \\Rightarrow \\cot\\tfrac{\\pi}{3} = \\tfrac{1}{\\sqrt{3}} \\approx 0.577","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1b5cc77b1a32c5', 'les_d1ace174ece365', 'learn', 5, 'callout', '{"tone":"tip","title":"Sketch from the reciprocal","body":"To sketch $y = \\sec x$, sketch $y = \\cos x$ first. Where cosine is 0, draw asymptotes; where cosine is ±1, secant touches it; elsewhere secant is farther from the axis."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_435f67ff8d61b7', 'les_d1ace174ece365', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"In surveying and optics, the secant of an angle gives the slant distance per unit of horizontal distance, for example the length of a ramp per meter of floor it covers."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_15a189d995305d', 'les_d1ace174ece365', 1, 'practice', 'numeric', 1, 'Find $\sec 0$.', '{"answer":1}', '[]', '$\frac{1}{\cos 0} = 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fd18331a82a10a', 'les_d1ace174ece365', 2, 'practice', 'numeric', 1, 'Find $\csc\frac{\pi}{6}$.', '{"answer":2}', '[]', '$\sin\frac{\pi}{6} = \frac{1}{2}$, so $\csc = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2ef424212d8c74', 'les_d1ace174ece365', 3, 'practice', 'numeric', 2, 'If $\sin\theta = 0.4$, find $\csc\theta$.', '{"answer":2.5,"tolerance":0.001}', '[]', '$\frac{1}{0.4} = 2.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_92cdb4dda9022c', 'les_d1ace174ece365', 4, 'practice', 'multiple_choice', 2, 'Where does $y = \cot x$ have vertical asymptotes?', '{"choices":["$x = \\frac{\\pi}{2} + k\\pi$","$x = k\\pi$","$x = 2k\\pi$","Nowhere"],"answer":1}', '[]', '$\cot x = \frac{\cos x}{\sin x}$ is undefined where $\sin x = 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1b5cc77b1a32c5', 'les_d1ace174ece365', 5, 'review', 'multiple_choice', 3, 'Which value can $\sec\theta$ never equal?', '{"choices":["−3","1","0.5","2"],"answer":2}', '[]', '$|\sec\theta| \ge 1$ always.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d1ace174ece365', (SELECT id FROM concepts WHERE slug = 'trig-functions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_d1ace174ece365', (SELECT id FROM formulas WHERE slug = 'trig-identities'), 1);

-- Lesson: significance-test-idea
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_74ced5c085688d', 'significance-test-idea', 'The idea of a significance test', 'State null and alternative hypotheses, interpret a P-value as the probability of results at least as extreme if the null is true, and draw conclusions using a significance level.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_792e5a139f3307', 'les_74ced5c085688d', 1, 'Write hypotheses H₀ and Hₐ about a parameter.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6aa399165df3a5', 'les_74ced5c085688d', 2, 'Interpret a P-value in context.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bd699b838cf7c1', 'les_74ced5c085688d', 3, 'Make and state a conclusion by comparing the P-value with α.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_792e5a139f3307', 'les_74ced5c085688d', 'learn', 1, 'definition', '{"term":"Hypotheses","body":"The null hypothesis $H_0$ is the claim of \"no effect\" or \"no difference,\" such as $p = 0.5$. The alternative $H_a$ is what we''re looking for evidence of, such as $p > 0.5$. Hypotheses are always about parameters."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6aa399165df3a5', 'les_74ced5c085688d', 'learn', 2, 'definition', '{"term":"P-value","body":"Assuming $H_0$ is true, the P-value is the probability of getting a statistic at least as extreme as the one observed. Small P-values are evidence against $H_0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bd699b838cf7c1', 'les_74ced5c085688d', 'learn', 3, 'definition', '{"term":"Conclusions","body":"Choose a significance level $\\alpha$ (often 0.05) in advance. If P-value $< \\alpha$, reject $H_0$: there is convincing evidence for $H_a$. Otherwise, fail to reject $H_0$: the evidence isn''t convincing. We never \"accept\" $H_0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9c0e9734f8ae6f', 'les_74ced5c085688d', 'learn', 4, 'worked_example', '{"title":"Is a coin biased toward heads? 100 flips give 61 heads.","steps":[{"latex":"H_0: p = 0.5,\\ H_a: p > 0.5","explanation":""},{"latex":"\\text{SD of } \\hat{p} \\text{ under } H_0 = \\sqrt{\\tfrac{0.5 \\cdot 0.5}{100}} = 0.05","explanation":""},{"latex":"z = \\frac{0.61 - 0.5}{0.05} = 2.2,\\ \\text{P-value} = P(Z \\ge 2.2) \\approx 0.014","explanation":""},{"latex":"0.014 < 0.05 \\Rightarrow \\text{reject } H_0","explanation":"Convincing evidence the coin favors heads."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fda8f3e02c488c', 'les_74ced5c085688d', 'learn', 5, 'callout', '{"tone":"warning","title":"What a P-value is not","body":"A P-value of 0.014 doesn''t mean there''s a 1.4% chance $H_0$ is true. It''s the chance of data this extreme if $H_0$ were true."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_167225798fb437', 'les_74ced5c085688d', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Drug trials, A/B tests on websites, and quality audits all use significance tests to decide whether an observed difference is bigger than chance alone would produce."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_792e5a139f3307', 'les_74ced5c085688d', 1, 'practice', 'multiple_choice', 1, 'A company claims 90% of customers are satisfied; you suspect fewer are. The alternative hypothesis is…', '{"choices":["$p = 0.9$","$p > 0.9$","$p < 0.9$","$\\hat{p} < 0.9$"],"answer":2}', '[]', '$H_a$ states what you''re seeking evidence for, about the parameter $p$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6aa399165df3a5', 'les_74ced5c085688d', 2, 'practice', 'multiple_choice', 2, 'P-value = 0.08 and $\alpha = 0.05$. The conclusion is…', '{"choices":["Reject H₀","Fail to reject H₀","Accept H₀","Accept Hₐ"],"answer":1}', '[]', '$0.08 > 0.05$: the evidence isn''t convincing at that level.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bd699b838cf7c1', 'les_74ced5c085688d', 3, 'practice', 'numeric', 2, 'Under $H_0: p = 0.5$ with $n = 100$, a sample gives $\hat{p} = 0.58$. Find $z$.', '{"answer":1.6,"tolerance":0.001}', '[]', '$\frac{0.58 - 0.5}{0.05} = 1.6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9c0e9734f8ae6f', 'les_74ced5c085688d', 4, 'review', 'multiple_choice', 3, 'A P-value of 0.003 means…', '{"choices":["H₀ has a 0.3% chance of being true","If H₀ were true, results this extreme would happen about 0.3% of the time","The effect is large","The sample is biased"],"answer":1}', '[]', 'The P-value is computed assuming $H_0$ is true; it says nothing directly about effect size.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d1e1e71a856b16', 'subj_math', 'significance-tests', 'Significance tests', 'Procedures that use sample data to weigh evidence against a claim about a population parameter.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_74ced5c085688d', (SELECT id FROM concepts WHERE slug = 'significance-tests'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_74ced5c085688d', (SELECT id FROM formulas WHERE slug = 'z-score'), 1);

-- Lesson: significance-tests-proportion
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ad6e275cd31cfe', 'significance-tests-proportion', 'Significance tests for a proportion', 'Carry out a one-sample z test for a proportion: state hypotheses, check conditions, compute the test statistic and P-value, and conclude in context.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_063100436cb76d', 'les_ad6e275cd31cfe', 1, 'Check conditions using the null value p₀.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6a2bf38f558f69', 'les_ad6e275cd31cfe', 2, 'Compute z = (p̂ − p₀)/√(p₀(1 − p₀)/n) and a one- or two-sided P-value.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6e01fbdbfa9ae1', 'les_ad6e275cd31cfe', 3, 'State a conclusion in context.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_063100436cb76d', 'les_ad6e275cd31cfe', 'learn', 1, 'definition', '{"term":"Test statistic","body":"$z = \\frac{\\hat{p} - p_0}{\\sqrt{p_0(1 - p_0)/n}}$. Use $p_0$, not $\\hat{p}$, in the standard deviation, because the test assumes $H_0$ is true. Large Counts: $np_0 \\ge 10$ and $n(1 - p_0) \\ge 10$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6a2bf38f558f69', 'les_ad6e275cd31cfe', 'learn', 2, 'definition', '{"term":"Four steps","body":"State: hypotheses, $\\alpha$, parameter. Plan: name the test, check conditions. Do: compute $z$ and the P-value. Conclude: compare with $\\alpha$, in context."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6e01fbdbfa9ae1', 'les_ad6e275cd31cfe', 'learn', 3, 'worked_example', '{"title":"A school claims 30% of students bike to school. In a random sample of 200, 72 bike. Test at $\\alpha = 0.05$.","steps":[{"latex":"H_0: p = 0.3,\\ H_a: p \\ne 0.3","explanation":"Two-sided: any difference."},{"latex":"200(0.3) = 60 \\ge 10,\\ 200(0.7) = 140 \\ge 10","explanation":"Large Counts met; Random given."},{"latex":"\\hat{p} = 0.36,\\ z = \\frac{0.06}{\\sqrt{0.21/200}} = \\frac{0.06}{0.0324} \\approx 1.85","explanation":""},{"latex":"\\text{P-value} = 2P(Z \\ge 1.85) \\approx 0.064","explanation":""},{"latex":"0.064 > 0.05 \\Rightarrow \\text{fail to reject } H_0","explanation":"Not convincing evidence the true proportion differs from 30%."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_34d77cfa0bee0a', 'les_ad6e275cd31cfe', 'learn', 4, 'callout', '{"tone":"tip","title":"Tests and intervals agree","body":"A two-sided test at $\\alpha = 0.05$ and a 95% confidence interval usually tell the same story: if $p_0$ is inside the interval, you''d fail to reject."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ffa8f65a1848e2', 'les_ad6e275cd31cfe', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Election officials test whether a sample of audited ballots matches the reported vote share; manufacturers test whether a defect rate exceeds a contract limit."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_063100436cb76d', 'les_ad6e275cd31cfe', 1, 'practice', 'numeric', 2, '$H_0: p = 0.4$, $n = 150$, $\hat{p} = 0.48$. Find $z$.', '{"answer":2,"tolerance":0.01}', '["$\\sqrt{0.4 \\cdot 0.6/150} = 0.04$."]', '$\frac{0.08}{0.04} = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6a2bf38f558f69', 'les_ad6e275cd31cfe', 2, 'practice', 'numeric', 2, 'For $H_a: p > p_0$ and $z = 2$, find the P-value to four decimal places.', '{"answer":0.0228,"tolerance":0.0002}', '[]', '$P(Z \ge 2) \approx 0.0228$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6e01fbdbfa9ae1', 'les_ad6e275cd31cfe', 3, 'practice', 'multiple_choice', 2, 'Why is $p_0$ used in the standard deviation of the test statistic?', '{"choices":["It''s always larger","The P-value is computed assuming H₀ is true","p̂ is unknown","It makes z positive"],"answer":1}', '[]', 'Everything in the calculation assumes the null value.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_34d77cfa0bee0a', 'les_ad6e275cd31cfe', 4, 'review', 'multiple_choice', 3, 'A two-sided test of $H_0: p = 0.5$ gives P-value 0.03. A 95% confidence interval from the same data would…', '{"choices":["contain 0.5","not contain 0.5","be centered at 0.5","be impossible to compute"],"answer":1}', '[]', 'Rejecting at 0.05 matches 0.5 lying outside the 95% interval.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d1e1e71a856b16', 'subj_math', 'significance-tests', 'Significance tests', 'Procedures that use sample data to weigh evidence against a claim about a population parameter.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ad6e275cd31cfe', (SELECT id FROM concepts WHERE slug = 'significance-tests'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_ad6e275cd31cfe', (SELECT id FROM formulas WHERE slug = 'z-score'), 1);

-- Lesson: sine-cosine-tangent
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_af40bbaa3d1b4e', 'sine-cosine-tangent', 'Sine, cosine and tangent', 'Define sine, cosine and tangent for any angle in standard position from a point on its terminal ray, and interpret tangent as the slope of that ray.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a0a796ae9a1b85', 'les_af40bbaa3d1b4e', 1, 'Place angles in standard position and find coterminal angles.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2cc217181d18f4', 'les_af40bbaa3d1b4e', 2, 'Compute sin, cos and tan from a point (x, y) on the terminal ray with r = √(x² + y²).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f53faf08c5e98e', 'les_af40bbaa3d1b4e', 3, 'Interpret tan θ as the slope of the terminal ray and use quadrant signs.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a0a796ae9a1b85', 'les_af40bbaa3d1b4e', 'learn', 1, 'definition', '{"term":"Angles in standard position","body":"An angle in standard position has its vertex at the origin and its initial ray on the positive $x$-axis. Counterclockwise rotation is positive. Angles that differ by a multiple of $2\\pi$ (or 360°) are coterminal."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2cc217181d18f4', 'les_af40bbaa3d1b4e', 'learn', 2, 'definition', '{"term":"Trig functions from a point","body":"If $(x, y)$ is on the terminal ray and $r = \\sqrt{x^2 + y^2}$, then $\\sin\\theta = \\frac{y}{r}$, $\\cos\\theta = \\frac{x}{r}$ and $\\tan\\theta = \\frac{y}{x}$. On the unit circle ($r = 1$), the point is $(\\cos\\theta, \\sin\\theta)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f53faf08c5e98e', 'les_af40bbaa3d1b4e', 'learn', 3, 'definition', '{"term":"Tangent as slope","body":"$\\tan\\theta = \\frac{y}{x} = \\frac{\\sin\\theta}{\\cos\\theta}$ is the slope of the terminal ray. It''s undefined where the ray is vertical ($\\cos\\theta = 0$)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c3d25f5773def9', 'les_af40bbaa3d1b4e', 'learn', 4, 'worked_example', '{"title":"The terminal ray passes through $(-3, 4)$","steps":[{"latex":"r = \\sqrt{9 + 16} = 5","explanation":""},{"latex":"\\sin\\theta = \\tfrac{4}{5},\\ \\cos\\theta = -\\tfrac{3}{5},\\ \\tan\\theta = -\\tfrac{4}{3}","explanation":"Quadrant II: sine positive, cosine and tangent negative."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cda5c4927e68a7', 'les_af40bbaa3d1b4e', 'experiment', 5, 'activity', '{"activity":"unit-circle","title":"Sine, cosine and tangent on the circle","params":{"degrees":true}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_25c06f54d559db', 'les_af40bbaa3d1b4e', 'experiment', 6, 'callout', '{"tone":"tip","title":"Signs by quadrant","body":"Quadrant I: all positive. II: sine positive. III: tangent positive. IV: cosine positive."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_480c0b1a140efa', 'les_af40bbaa3d1b4e', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Navigation and robotics describe directions as angles from a reference axis and convert them to $x$ and $y$ components with cosine and sine."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a0a796ae9a1b85', 'les_af40bbaa3d1b4e', 1, 'practice', 'numeric', 2, 'The terminal ray passes through $(5, -12)$. Find $\sin\theta$ to three decimal places.', '{"answer":-0.923,"tolerance":0.001}', '["$r = 13$."]', '$-\frac{12}{13} \approx -0.923$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2cc217181d18f4', 'les_af40bbaa3d1b4e', 2, 'practice', 'numeric', 1, 'What is $\tan 135°$?', '{"answer":-1}', '["Slope of the ray through (−1, 1)."]', 'Slope $\frac{1}{-1} = -1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f53faf08c5e98e', 'les_af40bbaa3d1b4e', 3, 'practice', 'multiple_choice', 1, 'In which quadrant are both $\sin\theta < 0$ and $\tan\theta > 0$?', '{"choices":["I","II","III","IV"],"answer":2}', '[]', 'Quadrant III: $x$ and $y$ both negative, so $\frac{y}{x} > 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c3d25f5773def9', 'les_af40bbaa3d1b4e', 4, 'practice', 'numeric', 2, 'Find the angle between 0° and 360° that is coterminal with −150°.', '{"answer":210,"unit":"°"}', '[]', '$-150 + 360 = 210$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cda5c4927e68a7', 'les_af40bbaa3d1b4e', 5, 'review', 'multiple_choice', 3, 'For which angle is $\tan\theta$ undefined?', '{"choices":["0","$\\frac{\\pi}{4}$","$\\frac{3\\pi}{2}$","$\\pi$"],"answer":2}', '[]', 'At $\frac{3\pi}{2}$ the ray is vertical, so $\cos\theta = 0$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_af40bbaa3d1b4e', (SELECT id FROM concepts WHERE slug = 'trig-functions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_af40bbaa3d1b4e', (SELECT id FROM formulas WHERE slug = 'trig-ratios'), 1);

-- Lesson: sinusoidal-data-modeling
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_8ab13181f03748', 'sinusoidal-data-modeling', 'Sinusoidal function context and data modeling', 'Build sinusoidal models y = a cos(b(x − h)) + k from maximum, minimum and timing information, and use them to predict.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f3f1aeee629ddb', 'les_8ab13181f03748', 1, 'Find amplitude, midline and period from data or a description.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e7ce0778f2eaba', 'les_8ab13181f03748', 2, 'Compute b = 2π / period and choose a phase shift from the time of a maximum or minimum.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_589ae949a6e742', 'les_8ab13181f03748', 3, 'Use the model to predict values and times.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f3f1aeee629ddb', 'les_8ab13181f03748', 'learn', 1, 'definition', '{"term":"Building the model","body":"$a = \\frac{\\max - \\min}{2}$, $k = \\frac{\\max + \\min}{2}$, $b = \\frac{2\\pi}{\\text{period}}$. Using cosine, set $h$ to the input of a maximum: $y = a\\cos(b(x - h)) + k$. (Use $-a$ and a minimum if that''s easier.)"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e7ce0778f2eaba', 'les_8ab13181f03748', 'learn', 2, 'worked_example', '{"title":"Daylight in a northern city: 15 h at most on day 172, 9 h at least, period 365 days","steps":[{"latex":"a = 3,\\ k = 12","explanation":""},{"latex":"b = \\tfrac{2\\pi}{365} \\approx 0.0172","explanation":""},{"latex":"D(t) = 3\\cos\\left(\\tfrac{2\\pi}{365}(t - 172)\\right) + 12","explanation":"Maximum at t = 172."}],"check":"Half a year later, $t \\approx 354.5$: $\\cos\\pi = -1$, so $D = 9$ hours, the minimum."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_589ae949a6e742', 'les_8ab13181f03748', 'learn', 3, 'worked_example', '{"title":"Temperature peaks at 30 °C at 3 p.m. and bottoms at 18 °C at 3 a.m. daily. Predict 9 a.m.","steps":[{"latex":"a = 6,\\ k = 24,\\ \\text{period } 24 \\text{ h}","explanation":""},{"latex":"9 \\text{ a.m. is a quarter period after the minimum}","explanation":"On the midline, rising."},{"latex":"T = 24\\ \\text{°C}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ed817e562020f2', 'les_8ab13181f03748', 'experiment', 4, 'activity', '{"activity":"sinusoid","title":"Fit amplitude, period, phase and midline","params":{"A":3,"B":0.5,"C":1,"D":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f95f120a1d3db0', 'les_8ab13181f03748', 'learn', 5, 'callout', '{"tone":"warning","title":"Real data aren''t perfect","body":"Measured data scatter around the model. A sinusoidal regression finds the best-fitting parameters; check residuals for patterns, and remember a model describes typical behavior, not exact values."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5f4f5dd08c741a', 'les_8ab13181f03748', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Utilities forecast electricity demand with sinusoidal models (daily and yearly cycles), and biologists model circadian rhythms the same way."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f3f1aeee629ddb', 'les_8ab13181f03748', 1, 'practice', 'numeric', 1, 'A sinusoid has period 12. Find $b$ to four decimal places.', '{"answer":0.5236,"tolerance":0.0001}', '[]', '$\frac{2\pi}{12} = \frac{\pi}{6} \approx 0.5236$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e7ce0778f2eaba', 'les_8ab13181f03748', 2, 'practice', 'numeric', 2, 'Water depth at a dock varies between 2 m and 10 m. What is the amplitude, in meters?', '{"answer":4,"unit":"m"}', '[]', '$\frac{10 - 2}{2} = 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_589ae949a6e742', 'les_8ab13181f03748', 3, 'practice', 'numeric', 2, 'Using $D(t) = 3\cos\left(\frac{2\pi}{365}(t - 172)\right) + 12$, how many hours of daylight are there on day 172?', '{"answer":15,"unit":"h"}', '[]', '$\cos 0 = 1$: $3 + 12 = 15$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ed817e562020f2', 'les_8ab13181f03748', 4, 'review', 'multiple_choice', 3, 'A buoy bobs between 1 m and 3 m above the sea floor, reaching the top at $t = 0$ s and again at $t = 4$ s. Which model fits?', '{"choices":["$y = \\cos\\left(\\frac{\\pi}{2}t\\right) + 2$","$y = 2\\cos(4t) + 1$","$y = \\sin\\left(\\frac{\\pi}{2}t\\right) + 2$","$y = \\cos(2\\pi t) + 2$"],"answer":0}', '["Period 4, so b = 2π/4."]', '$a = 1$, $k = 2$, $b = \frac{\pi}{2}$, and cosine starts at its maximum.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_8ab13181f03748', (SELECT id FROM concepts WHERE slug = 'trig-functions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_8ab13181f03748', (SELECT id FROM formulas WHERE slug = 'sinusoid'), 1);

-- Lesson: sinusoidal-functions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_b39753631f6415', 'sinusoidal-functions', 'Sinusoidal functions', 'Treat sine and cosine as sinusoidal functions: their period, amplitude and midline, where they increase and decrease, their concavity, and how cosine is a shifted sine.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e7bf40a6ccc4d4', 'les_b39753631f6415', 1, 'State the period, amplitude, midline, domain and range of y = sin θ and y = cos θ.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9d5dd9d9d2054f', 'les_b39753631f6415', 2, 'Identify intervals where sine and cosine increase, decrease, and are concave up or down.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_147528bc219be9', 'les_b39753631f6415', 3, 'Show that cos θ = sin(θ + π/2), so cosine is a horizontal shift of sine.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e7bf40a6ccc4d4', 'les_b39753631f6415', 'learn', 1, 'definition', '{"term":"Sinusoidal function","body":"A sinusoidal function is any transformation of $y = \\sin\\theta$. Both $\\sin\\theta$ and $\\cos\\theta$ have period $2\\pi$, amplitude 1, midline $y = 0$, domain all reals and range $[-1, 1]$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9d5dd9d9d2054f', 'les_b39753631f6415', 'learn', 2, 'definition', '{"term":"Cosine is a shifted sine","body":"$\\cos\\theta = \\sin\\left(\\theta + \\frac{\\pi}{2}\\right)$: the cosine graph is the sine graph shifted $\\frac{\\pi}{2}$ to the left."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_147528bc219be9', 'les_b39753631f6415', 'learn', 3, 'worked_example', '{"title":"Behavior of $\\sin\\theta$ on $[0, 2\\pi]$","steps":[{"latex":"\\text{increasing on } \\left[0, \\tfrac{\\pi}{2}\\right] \\cup \\left[\\tfrac{3\\pi}{2}, 2\\pi\\right]","explanation":""},{"latex":"\\text{decreasing on } \\left[\\tfrac{\\pi}{2}, \\tfrac{3\\pi}{2}\\right]","explanation":""},{"latex":"\\text{concave down on } (0, \\pi),\\ \\text{up on } (\\pi, 2\\pi)","explanation":"Inflection points where the graph crosses the midline."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_66d87c5573aff4', 'les_b39753631f6415', 'experiment', 4, 'activity', '{"activity":"sinusoid","title":"Shift sine into cosine","params":{"A":1,"B":1,"C":-1.6,"D":0}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bea1f7d3def025', 'les_b39753631f6415', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"With $C \\approx -\\frac{\\pi}{2} \\approx -1.57$, the graph of $\\sin(x - C)$ starts at its maximum, just like $\\cos x$. The sim rounds $C$ to 0.1, so this is approximate."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_361b31fde0354f', 'les_b39753631f6415', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Rates of change matter in context: a sinusoid changes fastest at the midline and slowest at its peaks, which is why tides rise fastest halfway between low and high tide."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e7bf40a6ccc4d4', 'les_b39753631f6415', 1, 'practice', 'multiple_choice', 1, 'What is the period of $y = \cos\theta$?', '{"choices":["$\\pi$","$2\\pi$","$\\frac{\\pi}{2}$","1"],"answer":1}', '[]', '$2\pi$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9d5dd9d9d2054f', 'les_b39753631f6415', 2, 'practice', 'multiple_choice', 2, 'On which interval is $y = \cos\theta$ decreasing?', '{"choices":["$[0, \\pi]$","$[\\pi, 2\\pi]$","$\\left[\\frac{\\pi}{2}, \\frac{3\\pi}{2}\\right]$","$\\left[-\\frac{\\pi}{2}, \\frac{\\pi}{2}\\right]$"],"answer":0}', '[]', 'Cosine falls from 1 at 0 to −1 at $\pi$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_147528bc219be9', 'les_b39753631f6415', 3, 'practice', 'multiple_choice', 2, 'Which equals $\cos\theta$ for all $\theta$?', '{"choices":["$\\sin\\left(\\theta - \\frac{\\pi}{2}\\right)$","$\\sin\\left(\\theta + \\frac{\\pi}{2}\\right)$","$-\\sin\\theta$","$\\sin(2\\theta)$"],"answer":1}', '["Check θ = 0."]', '$\sin\frac{\pi}{2} = 1 = \cos 0$, and the shift works for all $\theta$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_66d87c5573aff4', 'les_b39753631f6415', 4, 'review', 'multiple_choice', 3, 'Where is $y = \sin\theta$ changing fastest?', '{"choices":["At its maximum","At its minimum","Where it crosses the midline","It changes at a constant rate"],"answer":2}', '[]', 'The graph is steepest at the midline crossings (slope ±1) and flat at the extremes.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_b39753631f6415', (SELECT id FROM concepts WHERE slug = 'trig-functions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_b39753631f6415', (SELECT id FROM formulas WHERE slug = 'sinusoid'), 1);

-- Lesson: types-of-data
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_3559f1216e9acf', 'types-of-data', 'Types of data and variables', 'Identify individuals and variables in a data set, and classify variables as categorical or quantitative (discrete or continuous) to choose the right displays and summaries.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d68cd5734ebf49', 'les_3559f1216e9acf', 1, 'Identify the individuals and variables in a data set.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_de2b1f6026554c', 'les_3559f1216e9acf', 2, 'Classify variables as categorical or quantitative.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1eba765dba4724', 'les_3559f1216e9acf', 3, 'Distinguish discrete from continuous quantitative variables.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d68cd5734ebf49', 'les_3559f1216e9acf', 'learn', 1, 'definition', '{"term":"Individuals and variables","body":"Individuals are the objects described by a data set (people, animals, cars, days). A variable is a characteristic recorded for each individual."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_de2b1f6026554c', 'les_3559f1216e9acf', 'learn', 2, 'definition', '{"term":"Categorical and quantitative","body":"A categorical variable places each individual into a group (eye color, state of residence). A quantitative variable takes numerical values for which arithmetic makes sense (height, number of siblings)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1eba765dba4724', 'les_3559f1216e9acf', 'learn', 3, 'definition', '{"term":"Discrete and continuous","body":"A discrete quantitative variable takes countable values (number of pets). A continuous one can take any value in an interval (time to finish a race)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c12348a317dd1e', 'les_3559f1216e9acf', 'learn', 4, 'worked_example', '{"title":"A school records each student''s grade level, GPA, bus route number and number of absences.","steps":[{"latex":"\\text{individuals: students}","explanation":""},{"latex":"\\text{GPA: quantitative, continuous; absences: quantitative, discrete}","explanation":""},{"latex":"\\text{bus route number: categorical}","explanation":"Averaging route numbers means nothing; the numbers are labels."},{"latex":"\\text{grade level: often treated as categorical}","explanation":"It can be either, depending on the question you ask."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7aeb6efa9958c6', 'les_3559f1216e9acf', 'learn', 5, 'callout', '{"tone":"tip","title":"The arithmetic test","body":"If computing an average of the values would make sense, the variable is quantitative. ZIP codes, jersey numbers and phone numbers fail the test."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ca181cdc96b3ee', 'les_3559f1216e9acf', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"The type of variable decides everything that follows: bar and pie charts for categorical data; dot plots, histograms and box plots, with means and standard deviations, for quantitative data."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d68cd5734ebf49', 'les_3559f1216e9acf', 1, 'practice', 'multiple_choice', 1, 'A ZIP code is…', '{"choices":["Quantitative, discrete","Quantitative, continuous","Categorical","Neither"],"answer":2}', '["Would an average ZIP code mean anything?"]', 'ZIP codes are labels for regions.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_de2b1f6026554c', 'les_3559f1216e9acf', 2, 'practice', 'multiple_choice', 1, 'The number of goals scored in a soccer game is…', '{"choices":["Categorical","Quantitative, discrete","Quantitative, continuous","An individual"],"answer":1}', '[]', 'A count: 0, 1, 2, …');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1eba765dba4724', 'les_3559f1216e9acf', 3, 'practice', 'multiple_choice', 2, 'A survey asks 200 adults their age, favorite news source and weekly hours online. How many categorical variables are there?', '{"choices":["0","1","2","3"],"answer":1}', '[]', 'Only the news source is categorical; age and hours are quantitative.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c12348a317dd1e', 'les_3559f1216e9acf', 4, 'review', 'multiple_choice', 2, 'Which display fits a categorical variable?', '{"choices":["Histogram","Bar chart","Box plot","Dot plot of values"],"answer":1}', '[]', 'Bar charts show counts or percents in each category.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_f193b63a955a55', 'subj_math', 'data-types', 'Types of data', 'Categorical variables place individuals into groups; quantitative variables take numerical values that can be measured or counted.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_3559f1216e9acf', (SELECT id FROM concepts WHERE slug = 'data-types'));

-- Lesson: z-scores-percentiles
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_19b3a0033e0688', 'z-scores-percentiles', 'z-scores and percentiles', 'Measure relative standing with percentiles and z-scores, compare values from different distributions, and use the empirical rule.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_140089b60fa741', 'les_19b3a0033e0688', 1, 'Find and interpret the percentile of a value.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ab2266a78f8eb3', 'les_19b3a0033e0688', 2, 'Compute and interpret z-scores, and convert a z-score back to a value.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_039e39694fcff3', 'les_19b3a0033e0688', 3, 'Use z-scores to compare values from different distributions.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_140089b60fa741', 'les_19b3a0033e0688', 'learn', 1, 'definition', '{"term":"Percentile","body":"The $p$th percentile is the value with $p\\%$ of the data at or below it. Being at the 90th percentile means scoring as well as or better than 90% of the group."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ab2266a78f8eb3', 'les_19b3a0033e0688', 'learn', 2, 'formula', '{"latex":"z = \\frac{x - \\mu}{\\sigma} \\qquad x = \\mu + z\\sigma","title":"Standardizing and un-standardizing"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_039e39694fcff3', 'les_19b3a0033e0688', 'learn', 3, 'worked_example', '{"title":"Ana scores 85 on a test with mean 75 and SD 5. Ben scores 90 on a test with mean 80 and SD 8. Who did better relative to their class?","steps":[{"latex":"z_A = \\frac{85 - 75}{5} = 2","explanation":""},{"latex":"z_B = \\frac{90 - 80}{8} = 1.25","explanation":""},{"latex":"\\text{Ana did better relative to her class}","explanation":"Her score is farther above average in SD units."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_34e44a2f74e49c', 'les_19b3a0033e0688', 'learn', 4, 'definition', '{"term":"Empirical rule","body":"In an approximately normal distribution, about 68%, 95% and 99.7% of values lie within 1, 2 and 3 standard deviations of the mean. So $z = 1$ is near the 84th percentile, and $z = -2$ near the 2.5th."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_30ba0918d21c65', 'les_19b3a0033e0688', 'experiment', 5, 'activity', '{"activity":"normal-distribution","title":"From z-scores to percentiles"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e4ca147fb66cdb', 'les_19b3a0033e0688', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Pediatric growth charts report a child''s height as a percentile; standardized tests report scaled scores and percentiles so results compare across years."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_140089b60fa741', 'les_19b3a0033e0688', 1, 'practice', 'numeric', 1, 'Find the z-score of 62 when $\mu = 70$ and $\sigma = 4$.', '{"answer":-2}', '[]', '$\frac{62 - 70}{4} = -2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ab2266a78f8eb3', 'les_19b3a0033e0688', 2, 'practice', 'numeric', 2, 'IQ scores have mean 100 and SD 15. What score has $z = 1.5$?', '{"answer":122.5,"tolerance":0.01}', '[]', '$100 + 1.5(15) = 122.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_039e39694fcff3', 'les_19b3a0033e0688', 3, 'practice', 'numeric', 2, 'In an approximately normal distribution, about what percent of values lie below $z = -1$?', '{"answer":16,"tolerance":0.5,"unit":"%"}', '["68% lie within 1 SD; split the rest."]', '$(100 - 68)/2 = 16\%$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_34e44a2f74e49c', 'les_19b3a0033e0688', 4, 'practice', 'multiple_choice', 2, 'A runner''s time is at the 30th percentile of race times. That means…', '{"choices":["30% of runners were faster or tied","30% of runners had times at or below hers","She was 30% faster than average","She finished 30th"],"answer":1}', '[]', 'Percentile counts the share at or below the value. (For race times, lower is faster, so 30% of runners were at least as fast.)');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_30ba0918d21c65', 'les_19b3a0033e0688', 5, 'review', 'multiple_choice', 3, 'A value has $z = 0$. It equals…', '{"choices":["the median","the mean","zero","the standard deviation"],"answer":1}', '[]', '$x = \mu + 0 \cdot \sigma = \mu$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2485df8d7067e8', 'subj_math', 'z-scores', 'z-scores', 'The number of standard deviations a value is above or below the mean.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_19b3a0033e0688', (SELECT id FROM concepts WHERE slug = 'z-scores'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_19b3a0033e0688', (SELECT id FROM formulas WHERE slug = 'z-score'), 1);

